    description_ar: 'في وادٍ ساحر، يتبادل مخلوق غابة صغير وطائر مهيب أماكنهما بطريقة سحرية. تنطلق الكائنات في مغامرة العمر لإعادة التبديل، ليكشفان عن تهديد أكبر يهدد الوادي بأكمله.',
    description_en: 'A small woodland creature and a majestic bird, two natural sworn enemies of the Valley, magically trade places and set off on an adventure of a lifetime to switch back. Their journey soon uncovers a greater threat—one that could endanger not only their species, but the entire valley they call home.',
    description_fr: 'Dans une vallée enchantée, une petite créature des bois et un oiseau majestueux échangent magiquement leurs places. Ils se lancent dans l\'aventure de leur vie pour inverser le sort, découvrant une menace plus grande qui met en péril toute la vallée.',
    description_es: 'En un valle encantado, una pequeña criatura del bosque y un ave majestuosa intercambian mágicamente sus lugares. Se embarcan en la aventura de sus vidas para revertir el cambio, descubriendo una amenaza mayor que pone en peligro a todo el valle.',
    description_tr: 'Büyülü bir vadide, küçük bir orman yaratığı ve görkemli bir kuş sihirli bir şekilde yer değiştirir. Yerlerini geri almak için hayatlarının macerasına atılırlar ve tüm vadiyi tehlikeye atan daha büyük bir tehdidi ortaya çıkarırlar.',
