    description_ja: '魅惑的な谷で、小さな森の生き物と荘厳な鳥が魔法のように場所を交換します。 彼らは運命を逆転させるために一生に一度の冒険に乗り出し、谷全体を危険にさらすより大きな脅威を発見します。',
    description_pt: 'Num vale encantado, uma pequena criatura da floresta e um pássaro majestoso trocam magicamente de lugar. Eles embarcam na aventura de suas vidas para reverter a mudança, descobrindo uma ameaça que coloca todo o vale em perigo.',
