    description_tr: 'Corleone ailesi destanının bu epik devam filminde, genç Vito Corleone\'nin Sicilya\'da ve 1910\'larda New York\'ta büyümesine tanık oluyoruz. 1950\'lerde Michael Corleone, aile işini Las Vegas, Hollywood ve Küba\'ya yaymaya çalışır.',
