    description_ar: 'بينما يبحث فرانك كاسل عن معنى يتجاوز الانتقام، تجذبه قوة غير متوقعة إلى المعركة مرة أخرى.',
    description_en: 'As Frank Castle searches for meaning beyond revenge, an unexpected force pulls him back into the fight.',
    description_fr: 'Alors que Frank Castle cherche un sens à sa vie au-delà de la vengeance, il replonge contre toute attente au cœur du combat.',
    description_es: 'Mientras Frank Castle busca propósito más allá de la venganza, una fuerza inesperada lo arrastra de nuevo a la lucha.',
