    description_de: 'Frank Castle sucht nach seiner Bestimmung jenseits der Rache, wird aber unerwartet zurück in den Kampf gezogen.',
    description_ja: 'フランク・キャッスルが復讐を超えた意味を求める中、思いがけない力が彼を再び戦いに引き戻す。',
    description_pt: 'Enquanto Frank Castle procura um sentido para lá da vingança, é arrastado de volta à luta.',
