    id: '76', slug: 'rear-window', title: 'Rear Window', title_ar: 'النافذة الخلفية', year: 1954,
    director: 'Alfred Hitchcock', director_ar: 'Alfred Hitchcock',
    cast: ['James Stewart', 'Grace Kelly', 'Wendell Corey', 'Thelma Ritter', 'Raymond Burr', 'Judith Evelyn'],
    genres: ['thriller', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/ILVF0eJxHMddjxeQhswFtpMtqx.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/zZvtZZXRnZ4Tdcs0QEWaZZcIWy8.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=iZOTTxwzyMU',
    description_ar: 'المصور المحترف L.B. "جيف" كسر جيفريز ساقه أثناء تصويره في سباق سيارات. كان محتجزًا في شقته في نيويورك ، ويقضي وقته في النظر من النافذة الخلفية لملاحظة الجيران. عندما يبدأ في الشك في أن رجلاً عبر الفناء ربما قتل زوجته ، يستعين جيف بمساعدة صديقته المستشارة في مجال الأزياء في المجتمع الراقي وممرضته الزائرة للتحقيق.',
    description_en: 'A wheelchair-bound photographer spies on his neighbors from his apartment window and becomes convinced one of them has committed murder.',
    description_fr: 'À cause d\'une jambe cassée, le reporter-photographe L. B. Jefferies est contraint de rester chez lui dans un fauteuil roulant. Homme d\'action et amateur d\'aventures, il s\'aperçoit qu\'il peut tirer parti de son immobilité forcée en étudiant le comportement des habitants de l\'immeuble qu\'il occupe dans Greenwich Village. Et ses observations l\'amènent à la conviction que Lars Thorwald, son voisin d\'en face, a assassiné sa femme. Sa fiancée, Lisa Fremont, ne le prend tout d\'abord pas au sérieux, ironisant sur l\'excitation que lui procure sa surveillance, mais finit par se prendre au jeu.',
    description_es: 'Un reportero fotográfico se ve obligado a permanecer en reposo con una pierna escayolada. A pesar de la compañía de su novia y de su enfermera, procura escapar al tedio, observando desde la ventana de su apartamento con unos prismáticos lo que ocurre en las viviendas de enfrente. Debido a una serie de extrañas circunstancias empieza a sospechar de un vecino cuya mujer ha desaparecido.',
    description_tr: 'Fotoğrafçı L. B. “Jeff” Jeffries, geçirdiği kaza sonucunda bacağını kırar. New York’taki apartman dairesinde zorunlu tatili sırasında arka penceresinden komşularını dürbünle seyrederek zaman geçirmektedir. Jeff, yine bir seyri sırasında komşusunun, karısını öldürdüğünden şüphelenir. Olayı araştırmaları için fotomodel sevgilisi Lisa Carol Fremont ve hasta bakıcısı Stella’dan yardım ister.',
    description_de: 'Jeff ist Pressefotograf und durch einen Beinbruch an den Rollstuhl und seine Wohnung gefesselt. Um der drohenden Langeweile zu entkommen, beobachtet er aus seinem Fenster zum Hof die Nachbarschaft und lernt sie so bestens und von allen Seiten kennen. Seine Freundin Lisa ist zunächst wenig begeistert davon, aber schließlich ist die Neugier doch stärker. Als die beiden im Leben ihres Nachbarn von gegenüber, Mr. Thorwald, einige Merkwürdigkeiten beobachten, keimt in ihnen der Verdacht, dass mit dessen Frau etwas nicht stimmt. Jeff wittert Mord und lässt den Hinterhof von nun an nicht eine Sekunde aus den Augen …',
    description_ja: 'カメラマンのジェフは足を骨折し、ニューヨークはグリニッチ・ヴィレッジのアパートで療養中。身動きの取れない彼にとって退屈しのぎの楽しみは、窓から見える中庭と向いのアパートの住人たちを眺める事だけ。だが、その中で、セールスマンの夫と激しい口論をしていた病床の妻の姿が見えなくなった事に気づいた。セールスマンの様子を窺う内に、ジェフはその男が女房を殺したのではないかと推測、恋人のリザと看護人ステラの協力を得て調査を始めるのだが……。',
    description_pt: 'Quando o fotógrafo profissional Jeff Jeffries se vê obrigado a permanecer numa cadeira de rodas devido a uma perna partida, nasce nele uma obsessão pela observação dos dramas privados dos seus vizinhos. Mas ele acaba por ver cenas que o levam a acreditar que um deles matou a própria esposa.',
    rating_overall: 8.4, rating_story: 8.4, rating_acting: 8.5, rating_direction: 8.3, rating_cinematography: 8.1, rating_music: 7.9,
    imdb_rating: 8.3, rotten_tomatoes: 83,
    budget_million: 1.0,
    box_office_million: 37,
    duration: 112, language: 'EN', country: 'US',
