    id: '79', slug: 'back-to-the-future', title: 'Back to the Future', title_ar: 'العودة إلى المستقبل', year: 1985,
    director: 'Robert Zemeckis', director_ar: 'Robert Zemeckis',
    cast: ['Michael J. Fox', 'Christopher Lloyd', 'Crispin Glover', 'Lea Thompson', 'Claudia Wells', 'Thomas F. Wilson'],
    genres: ['adventure', 'comedy', 'scifi'],
    poster_url: 'https://image.tmdb.org/t/p/w500/vN5B5WgYscRGcQpVhHl6p9DDTP0.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/5bzPWQ2dFUl2aZKkp7ILJVVkRed.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=ez6WQ7IX72U',
    description_ar: 'أُعيد مراهق الثمانينيات مارتي ماكفلي بطريق الخطأ إلى عام 1955 ، مما أدى عن غير قصد إلى تعطيل الاجتماع الأول لوالديه وجذب اهتمام والدته العاطفي. يجب على مارتي إصلاح الضرر الذي لحق بالتاريخ من خلال إحياء الرومانسية بين والديه ، وبمساعدة صديقه المخترع غريب الأطوار دوك براون - يعود إلى عام 1985.',
    description_en: 'Eighties teenager Marty McFly is accidentally sent back in time to 1955, inadvertently disrupting his parents\' first meeting and attracting his mother\'s romantic interest. Marty must repair the damage to history by rekindling his parents\' romance and - with the help of his eccentric inventor friend Doc Brown - return to 1985.',
    description_fr: 'En 1985, Marty, un adolescent comme les autres, mène une existence morne et ennuyeuse. Heureusement, il est épris de la jolie Jennifer et entretient une profonde amitié avec Doc, un savant fou qui prétend avoir inventé une machine à explorer le temps. Un jour, Doc invite Marty à l\'essayer…',
    description_es: 'El adolescente Marty McFly es amigo de Doc, un científico al que todos toman por loco. Cuando Doc crea una máquina para viajar en el tiempo, un error fortuito hace que Marty llegue a 1955, año en el que sus futuros padres aún no se habían conocido. Después de impedir su primer encuentro, deberá conseguir que se conozcan y se casen; de lo contrario, su existencia no sería posible.',
    description_tr: 'Dönemin özellikle tasarımıyla öne çıkan otomobillerinden olan bir DeLoran\'ın içine gizlenmiş icat, Marty\'i yanlışlıkla 50\'lere geri götürür. Sorumsuz delikanlı bu gösterişsiz Amerikan kasabasında bir kazaya yol açar ve müstakbel anne ve babasının tanışmasına engel olur. Böylece kendisi de hiç doğmamış olacağı için bu durumu düzeltmesi gerekmektedir. Ama hayat sandığından daha karmaşıktır ve sorumluluk kelimesinin anlamını öğrenmek zorundadır.',
    description_de: 'Der Teenager Marty McFly wird mit der Zeitmaschine seines Freundes, dem skurrilen Wissenschaftler Dr. Emmett Brown, versehentlich ins Jahr 1955 geschleudert. Dort verhindert er zunächst unabsichtlich, dass sich seine zukünftigen Eltern kennen lernen und in einander verlieben, womit er seine eigene Zeugung gefährdet. Zu allem Überfluss verguckt sich seine Mutter auch noch in ihn. Ihm bleibt nun eine Woche Zeit, seinen tollpatschigen Vater mit seiner Mutter zu verkuppeln und gemeinsam mit Docs dreißig Jahre jüngerem alter Ego einen Plan zu entwickeln, wie sie das bevorstehende große Gewitter nutzen können, um ihn in die Gegenwart zurück zu schicken.',
    description_ja: 'スティーブン・スピルバーグとロバート・ゼメキスが贈るSFアドベンチャーシリーズ第1弾。高校生のマーティは、科学者・ドクの発明したタイムマシン・デロリアンで過去にタイムスリップしてしまう。',
    description_pt: 'Marty Mcfly, um típico jovem americano dos anos 80, acciona acidentalmente uma máquina do tempo construída num Delorean pelo excêntrico cientista Doc e vai parar ao ano de 1955. Sem saber como voltar ao presente, conhece a sua futura mãe antes do casamento com o seu pai, colocando assim em risco a sua própria existência no futuro.',
    rating_overall: 8.4, rating_story: 8.4, rating_acting: 8.5, rating_direction: 8.3, rating_cinematography: 8.1, rating_music: 7.9,
    imdb_rating: 8.3, rotten_tomatoes: 83,
    budget_million: 19.0,
    box_office_million: 381,
