    id: '81', slug: 'the-wild-robot', title: 'The Wild Robot', title_ar: 'الروبوت البري', year: 2024,
    director: 'Chris Sanders', director_ar: 'Chris Sanders',
    cast: ['Lupita Nyong\'o', 'Pedro Pascal', 'Kit Connor', 'Bill Nighy', 'Stephanie Hsu', 'Matt Berry'],
    genres: ['drama', 'animation', 'scifi'],
    poster_url: 'https://image.tmdb.org/t/p/w500/eG9lz41mJqsI4J6ubMtVqD26q2J.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/mQZJoIhTEkNhCYAqcHrQqhENLdu.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=VUCNBAmse04',
    description_ar: 'بعد تحطم مركبتها، تجد روبوت ذكية تُدعى (روز) نفسها على متن جزيرة معزولة، وفي سبيل النجاة من الظروف البيئية القاسية تنشأ بينها وبين الحيوانات رابطة قوية، وتعتني في طريقها بصغير إوز يتيم.',
    description_en: 'After a shipwreck, an intelligent robot called Roz is stranded on an uninhabited island. To survive the harsh environment, Roz bonds with the island\'s animals and cares for an orphaned baby goose.',
    description_fr: 'L’incroyable épopée d\'un robot -- l\'unité ROZZUM 7134 alias "Roz" -- qui après avoir fait naufrage sur une île déserte doit apprendre à s\'adapter à un environnement hostile en nouant petit à petit des relations avec les animaux de l\'île. Il finit par adopter le petit d’une oie, un oison, qui s\'est retrouvé orphelin.',
    description_es: 'Esta aventura épica cuenta la historia de una robot, Rozzum 7-1-3-4, "Roz" para abreviar, que naufraga en una isla inhabitada y debe aprender a adaptarse a los entornos rigurosos construyendo relaciones con los animales de la isla y convirtiéndose en la madre adoptiva de una cría de ganso huérfana.',
    description_tr: 'Bu destansı macera, ıssız bir adaya düşen ve zorlu çevre koşullarına uyum sağlamayı öğrenmesi gereken bir robotun -ROZZUM ünite 7134’ün, kısaca “Roz”un- yavaş yavaş adadaki hayvanlarla ilişki kurmasını ve yetim bir kaz yavrusunun evlat edinmesini konu alıyor.',
    description_de: 'Rozzum 7134 – kurz „Roz“ – ist kein gewöhnlicher Roboter. Sie wurde eigentlich als Unterstützung für eine futuristische urbane Welt entwickelt, doch nun hat sie Schiffbruch erlitten und ist auf einer einsamen Insel gestrandet. Mit Mühe baut sie Beziehungen zu den zunächst argwöhnischen Tieren auf und lernt, sich an die ungewohnte, raue Umgebung anzupassen. Das große Abenteuer beginnt, als sie durch einen Zufall zur Beschützerin eines hilflosen, verwaisten Gänsekükens wird und die wahre Bedeutung des Lebens entdeckt.',
    description_ja: '嵐の夜、人間をサポートするプログラムがインストールされた〈最新型アシストロボット〉が入った箱が、無人島に流れ着いた。偶然にも起動ボタンが押されて、“彼女”は目覚める。誰もいない大自然の中で、ロズは命令を求め、歩き出す。島の動物たちからは“怪物”呼ばわりされ、大自然を孤独にあてもなくさまようロズ。誰からも命令されない、過酷な野生の島では、ロズに組み込まれたプログラムは通用しない。しかしある日、ひとつの“小さな出会い”をきっかけに、ロズに思いもよらない変化の兆しが現れ始める――',
    description_pt: 'A aventura épica acompanha a viagem de um robot, ROZZUM unidade 7134, "Roz" para abreviar, que naufraga numa ilha desabitada e tem de aprender a adaptar-se ao ambiente agreste, construindo gradualmente relações com os animais da ilha e adotando um pequeno ganso órfão.',
    rating_overall: 8.4, rating_story: 8.4, rating_acting: 8.5, rating_direction: 8.3, rating_cinematography: 8.1, rating_music: 7.9,
    imdb_rating: 8.3, rotten_tomatoes: 83,
    budget_million: 78.0,
    box_office_million: 332,
