    id: '84', slug: 'dead-poets-society', title: 'Dead Poets Society', title_ar: 'جمعية الشعراء الموتى', year: 1989,
    director: 'Peter Weir', director_ar: 'Peter Weir',
    cast: ['Robin Williams', 'Robert Sean Leonard', 'Ethan Hawke', 'Josh Charles', 'Gale Hansen', 'Dylan Kussman'],
    genres: ['drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/erzbMlcNHOdx24AXOcn2ZKA7R1q.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/yYvBNN96Ym3wtPxGCFl7F888WwB.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=s_jsDreXFZU',
    description_ar: 'في مدرسة داخلية قديمة الطراز في نيو إنجلاند ، يلهم مدرس اللغة الإنجليزية الشغوف طلابه بالتمرد على الأعراف والاستيلاء على إمكانات كل يوم ، مما يؤدي إلى ازدراء مدير المدرسة الصارم.',
    description_en: 'At an elite, old-fashioned boarding school in New England, a passionate English teacher inspires his students to rebel against convention and seize the potential of every day, courting the disdain of the stern headmaster.',
    description_fr: 'Todd Anderson est un garçon plutôt timide. Désormais élève de la prestigieuse académie Welton, réputée pour être l\'une des plus fermées et austères des États-Unis, tout le monde attend de lui qu\'il suive les traces de son frère, qui avait fait à Welton de brillantes études.  C\'est là qu\'il va faire la rencontre de M. Keating, un professeur de lettres anglaises qui, c\'est le moins que l\'on puisse dire, sort des sentiers battus. Jour après jour, M. Keating encourage ses élèves à penser par eux-mêmes et à refuser l\'ordre établi. Cette rencontre va bouleverser la vie du jeune Todd, mais aussi celle de ses amis.',
    description_es: 'En un elitista y estricto colegio privado de Nueva Inglaterra, un grupo de alumnos descubrirá la poesía, el significado de "Carpe Diem" -aprovechar el momento- y la importancia de perseguir los sueños, gracias a un excéntrico profesor que despierta sus mentes por medio de métodos poco convencionales.',
    description_tr: '50\'lerin Welton Akademisi, ciddi, disiplinli ve akademik çevrelerde saygınlığı yüksek olan bir okuldur. Okul yönetiminin muhafazakar ve ortodoks tavırları okulu öğrenciler için sıkıcı ve bunaltıcı bir hale getirmektedir. Fakat yeni ingilizce öğretmeni John Keating\'in okula atanmasıyla çok şey değişecektir.Keating öğrencilerine ders kitaplarını yırtıp atmalarını, kalıplaşmış düşünce şekillerinden uzaklaşmalarını ve hayatlarını dolu dolu yaşamalarını öğütlemesiyle okulun statükocu tavrına son derece zıt bir profil çizmektedir. Öğrencilerini şiir ve nitelikli edebi yapıtlarla tanıştıran Keating onların pek çoğu üzerinde derin bir etki yaratır ve onların geleceğe dair hayallerinin şekillenmesini sağlar. Elbette Keating’in yaklaşımının okul yönetimi tarafından farkedilmesi ve üstüne gidilmesi uzun sürmeyecektir. Fakat okul müdürü Nolan Keating’i okuldan uzaklaştırma kararı aldığında hayatlarını değiştirdiği öğrencileri Keating’i savunmak için harekete geçerler.',
    description_de: 'Der neue Literaturlehrer John Keating bringt 1959 frischen Wind in das Traditionsinternat Welton und inspiriert seine ansonsten zur Disziplin erzogenen Schüler durch sein unorthodoxes Vermitteln von Poesie zu freiem Denken. Des Nachts treffen sie sich zu Lesungen in einer alten Höhle. Der Junge Neil entdeckt seine Liebe zur Schauspielerei. Als sein gestrenger Vater davon erfährt, nimmt er Neil von der Schule. Seiner Träume beraubt, erschießt sich Neil. Keating wird verantwortlich gemacht und der Schule verwiesen. Als er seine Bücher abholt, sprechen ihm seine Schüler durch kollektive Verweigerung ihren Dank für seine Menschlichkeit aus.',
    description_ja: '1959年、バーモントにある全寮制の名門進学校にやって来た新任の英語教師。破天荒な授業を通して、詩の美しさや人生の素晴らしさを説く教師に惹かれていった生徒たちは、彼がかつて学生だった頃に作っていた“死せる詩人の会”という同好会を自分たちの手で復活させる。ドラマの背景となる、初秋から冬にかけてのニューイングランド地方の風景も美しい。',
    description_pt: 'John Keating é o novo professor de Literatura Inglesa de um prestigiado e conservador colégio interno norte-americano da década de cinquenta. Através de métodos pouco convencionais de ensino, irá conseguir que os seus alunos encarem a poesia de uma forma nova e diferente, e comecem a pensar por si mesmos e a perseguir as suas paixões.',
    rating_overall: 8.4, rating_story: 8.4, rating_acting: 8.5, rating_direction: 8.3, rating_cinematography: 8.1, rating_music: 7.9,
    imdb_rating: 8.3, rotten_tomatoes: 83,
    budget_million: 16.4,
    box_office_million: 236,
