    id: '93', slug: 'hotarubi-no-mori-e', title: 'Hotarubi no Mori e', title_ar: '蛍火の杜へ', year: 2011,
    director: 'Takahiro Omori', director_ar: 'Takahiro Omori',
    cast: ['Izumi Sawada', 'Hayato Taya', 'Ayane Sakura', 'Koki Uchiyama', 'Shinpachi Tsuji', 'Kanehira Yamamoto'],
    genres: ['romance', 'animation', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/mDqzHV8UXWWNpZkoAbKmKX1ZxEE.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/qknxyRgP6UTmwJ4B9tDAmzHMq7u.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=qXLSRH31Yao',
    description_ar: 'One hot summer day a little girl gets lost in an enchanted forest of the mountain god where spirits reside. A young boy appears before her, but she cannot touch him for fear of making him disappear. And so a wondrous adventure awaits...',
    description_en: 'One hot summer day a little girl gets lost in an enchanted forest of the mountain god where spirits reside. A young boy appears before her, but she cannot touch him for fear of making him disappear. And so a wondrous adventure awaits...',
    description_fr: 'Perdue dans une forêt à côté de la maison de son grand-père où elle se rend chaque été, la petite Hotaru fait la rencontre d\'un garçon mystérieux qui l\'aide à retrouver son chemin. Elle commence à lui rendre visite tous les étés et l\'esprit attend ces moments partagés avec Hotaru, au risque de disparaître…',
    description_es: 'De niña, Hotaru se pierde en un bosque y conoce a Gin, un joven enmascarado que no puede ser tocado por humanos debido a un hechizo. Cada verano, ella regresa para verlo, creando un vínculo especial que desafía el paso del tiempo.',
    description_tr: 'Hotaru, yazları büyükbabasının evine kalmaya giden altı yaşında bir kızdır. Bir gün, içinde dağ ruhlarının yaşadığı söylenen ormanda kaybolur. Ne yapacağını bilemezken karşısında Gin adında bir genç belirir. Gin, ona eğer bir insan kendisine dokunursa yok olacağını söyler. Bir insanın dokunuşuyla yok olmaya mahkûm olan maskeli ruh Gin\'le Hotaru\'nun yıllara yayılan imkansız aşkını anlatan hikaye, fiziksel temasın yasak olduğu bu naif bağın hem ne kadar derin hem de trajik bir vedaya ne kadar yakın olduğunu işler.',
    description_de: 'Als sechsjähriges Mädchen hat sich Hotaru im Wald des Berggottes verirrt. Gerettet wird sie von dem Youkai-Jungen Gin, der sie weinend und verzweifelt unter einem Baum findet. Aus Dankbarkeit verspricht sie ihm, ihn auch am nächsten Tag zu besuchen. Seit damals kommt Hotaru jeden Tag ihrer Sommerferien in den verzauberten Wald hinter dem Dorf ihres Onkels. Über die Jahre entwickelt sich aus der Freundschaft zu Gin mehr, doch dürfen sich die beiden niemals zu nahe kommen. Sollte Gin von einem Menschen berührt werden, dann wird er für immer verschwinden …',
    description_ja: '夏休みに、祖父の家に遊びに来ていた少女・蛍は、妖怪たちが住むといわれる“山神の森”へ迷い込んでしまう。途方に暮れ、泣き出した蛍の前に現れたのは、狐の面を被った少年・ギン。ギンに助けられた蛍は、毎年夏になると、ギンのもとを訪れるようになる。そして、ふたりはいつしか惹かれあってゆく。だがギンは、人でも妖怪でもない、触れると消えてしまうという不思議な存在だった。',
    description_pt: 'A história gira em torno de uma menina chamada Hotaru. Ela perde-se numa floresta conhecida por ser habitada por espíritos. Lá, Hotaru encontra um jovem que usa uma máscara de raposa. Ele diz ser um espírito amaldiçoado que desaparecerá se for tocado por um humano.',
    rating_overall: 8.3, rating_story: 8.4, rating_acting: 8.5, rating_direction: 8.3, rating_cinematography: 8.1, rating_music: 7.9,
    imdb_rating: 8.3, rotten_tomatoes: 83,
    duration: 45, language: 'JA', country: 'JP',
