    id: '95', slug: 'miracle-in-cell-no-7', title: 'Miracle in Cell No. 7', title_ar: 'معجزة في الزنزانة 7', year: 2019,
    director: 'Mehmet Ada Öztekin', director_ar: 'Mehmet Ada Öztekin',
    cast: ['Aras Bulut İynemli', 'Nisa Sofiya Aksongur', 'İlker Aksum', 'Mesut Akusta', 'Yıldıray Şahinler', 'Yurdaer Okur'],
    genres: ['drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/bOth4QmNyEkalwahfPCfiXjNh1r.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/inEy3A5OPgeYW4rjRiGycfEeQzA.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=bDAkHkR6fwA',
    description_ar: 'بعد انفصاله عن ابنته ، يجب على الأب الذي يعاني من إعاقة ذهنية إثبات براءته عندما يُسجن لوفاة طفل قائد عسكري.',
    description_en: 'Separated from his daughter, a father with an intellectual disability must prove his innocence when he is jailed for the death of a commander\'s child.',
    description_fr: 'Séparé de sa fille, un père avec un handicap mental doit prouver son innocence lorsqu\'il est arrêté pour le meurtre d\'une enfant.',
    description_es: 'Un hombre con discapacidad intelectual es injustamente encarcelado por la muerte de una niña, y debe demostrar su inocencia para poder estar de nuevo con su hija.',
    description_tr: 'Darbe döneminde bir Ege kasabasında, canından çok sevdiği küçük kızı ve babaannesiyle birlikte yaşayan Memo, mental yetersizliği olan ama küçük dünyasında mutlu yaşayan bir çobandır. 1983 yılında bir gün, sıkıyönetim komutanının kızının ölümü üzerine kalan ve sıradan hayatı birden altüst olan Memo, idam cezasına çarptırılır ve böylece ‘Yedinci Koğuş’a gelir. Burada hayatta kalması pek mümkün görünmemektedir. Fakat başta onu nefretle karşılayan tüm koğuş, onun iyilik dolu kalbini görür, yavaş yavaş Memo’nun cinayet işleyebilecek bir kişiliği olmadığına ikna olmaya başlar ve zamanla hayatına dokunduğu herkes Memo’nun hayatını kurtarmak için seferber olur. Herkes adalet peşindeyken Memo ve kızı Ova’nın tek isteği birbirlerine kavuşmaktır. Memo suçsuzdur ve şimdi yaşamına geri dönebilmesi için bir mucizeye ihtiyacı vardır.',
    description_de: 'Als Hirte führt Memo Anfang der 1980er-Jahre ein bescheidenes aber glückliches Leben zusammen mit seiner Mutter und seiner sechsjährigen Tochter Ova in einem kleinen Dorf der Agäis-Region. Von den Unruhen des Staatsstreichs bekommen sie in der Einöde nichts mit. Das unbescholtene Leben nimmt ein jähes Ende, als dem Familienvater eines Tages der Tod der Tochter eines Militärangehörigen zu Last gelegt wird. Ihm wird der Prozess gemacht, er wird zum Tode verurteilt und in Zelle Sieben des Gefängnisses gesteckt. Die Aussichten, dass der geistig behinderte Mann das Leben in dieser Zelle überleben wird, stehen schlecht. Obwohl ihn die anderen Insassen anfangs nicht gut behandeln, stellen sie bald fest, dass Memo kein schlechter Mensch ist, und sind immer mehr davon überzeugt, dass so jemand wie er, keinen Mord begehen kann.',
    description_ja: '軍司令官の子供を殺害した罪で投獄され、愛する娘と離ればなれになった知的障害を持つ男。死刑判決を受けながらも、ひたすら無実を訴え続けるが...。',
    description_pt: 'Na Turquia dos anos 80, um pastor mentalmente atrasado é acusado injustamente de matar uma criança. Preso, é espancado e condenado à forca, mas a sua bondade inata contagia todos e convence toda a gente da sua inocência. Ao mesmo tempo que uns tentam ajudá-lo a sair da prisão vivo, outros tentarão ajudá-lo a não perder contacto com Ova, a sua filha de seis anos, a quem ele ama mais do que tudo na vida.',
    rating_overall: 8.4, rating_story: 8.4, rating_acting: 8.5, rating_direction: 8.3, rating_cinematography: 8.1, rating_music: 7.9,
    imdb_rating: 8.3, rotten_tomatoes: 83,
    box_office_million: 28,
