    id: '96', slug: 'city-lights', title: 'City Lights', title_ar: 'City Lights', year: 1931,
    director: 'Charlie Chaplin', director_ar: 'Charlie Chaplin',
    cast: ['Charlie Chaplin', 'Virginia Cherrill', 'Florence Lee', 'Harry Myers', 'Al Ernest Garcia', 'Hank Mann'],
    genres: ['comedy', 'drama', 'romance'],
    poster_url: 'https://image.tmdb.org/t/p/w500/bXNvzjULc9jrOVhGfjcc64uKZmZ.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/qhKMAWxuu4TXCJCWVMqfveqanMP.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=7vl7F8S4cpQ',
    description_ar: 'في هذا الفيلم الصامت من عصر الصوت ، يقع متشرد في حب بائع زهور أعمى جميل.',
    description_en: 'A tramp falls in love with a beautiful blind flower girl. His on-and-off friendship with a wealthy man allows him to be the girl\'s benefactor and suitor.',
    description_fr: 'Un vagabond s’éprend d’une belle et jeune vendeuse de fleurs aveugle qui vit avec sa mère, couverte de dettes. Suite à un quiproquo, la fleuriste s’imagine le misérable, qui vient de lui acheter une fleur, en milliardaire…',
    description_es: 'Un pobre vagabundo (Charles Chaplin) pasa mil y un avatares para conseguir dinero y ayudar a una pobre chica ciega (Virginia Cherill) de la que se ha enamorado.',
    description_tr: 'Şehir Işıkları, görme engelli genç bir kızla evsiz bir gencin hikayesini anlatıyor. Kör bir çiçekçiye aşık olan ve sokaklarda yaşayan iyi niyetli bir serseri, kıza kendisini varlıklı biri olarak tanıtır. Bir milyonerin hayatını kurtarmıştır ve onun kendisine yardım edeceğine güvenmektedir. Adamı ziyaret edip sevdiği kızın gözlerini ameliyat ettirebilecek kadar para ödünç alabileceğini düşünür. Ama zengin insanlar aslında ikiyüzlü bir yaşam sürmektedirler. Mesaj sessiz, fakat evrenseldir: aşkın gözü kördür...',
    description_de: 'Mit „Lichter der Großstadt“ erstellte Charlie Chaplin einen Stummfilm, als sich der Tonfilm zu etablieren begann. Der Film um die Liebe eines mittellosen Mannes zu einem Blumenmädchen wurde ein Riesenerfolg und der Film gilt bis heute als Kultfilm.',
    description_ja: '世の中は極端に不景気。小男で風彩もあがらず、服装もみすぼらしく、職もなく住むところもないチャーリーは、職にありつけそうもなく、毎日あちこちさすらい歩いてフーテン暮らしをしていた。そんな彼が一人の娘に恋をした。街角で花を売っている、盲目の貧しい娘だ。彼は彼女の目を治す為に、金を稼ごうと一大決心をするが……。',
    description_pt: 'O Vagabundo transforma-se num homem do lixo, num pugilista, num falso milionário e no salvador de um milionário com intentos suicidas, tudo para obter o dinheiro necessário para uma operação que restituirá a visão a uma jovem vendedora de flores cega.',
    rating_overall: 8.3, rating_story: 8.3, rating_acting: 8.4, rating_direction: 8.2, rating_cinematography: 8, rating_music: 7.8,
    imdb_rating: 8.2, rotten_tomatoes: 82,
    budget_million: 1.5,
    box_office_million: 4,
    duration: 87, language: 'EN', country: 'US',
    reviews_count: 3953, is_featured: false, release_date: '1931-02-06', tags: ['comedy', 'drama', 'romance', '1931', 'chaplin'],
