    poster_url: 'https://image.tmdb.org/t/p/w500/q125RHUDgR4gjwh1QkfYuJLYkL.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/cYQvXNPZLow73lhspVQ7CYlT3Mi.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=taE3PwurhYM',
    description_ar: 'تنشأ صداقة غير متوقعة بين ساعي بريد أناني وصانع ألعاب منعزل، فيبعثان الأمل في بلدة باردة ومظلمة تفتقر بشدّة إلى البهجة... فماذا فعلا؟',
    description_en: 'A selfish postman and a reclusive toymaker form an unlikely friendship, delivering joy to a cold, dark town that desperately needs it.',
    description_fr: 'Un facteur égoïste et un fabricant de jouets solitaire forgent une amitié improbable, apportant la joie à une bourgade sombre et froide qui en a désespérément besoin.',
    description_es: 'Un cartero egoísta y un juguetero huraño forjan una amistad muy especial, que sembrará la alegría en un pueblo frío y oscuro.',
    description_tr: 'Bencil bir postacı ile münzevi bir oyuncakçı arasında kurulan beklenmedik dostluk, soğuk ve karanlık bir kasabaya ihtiyacı olan neşeyi getirir.',
    description_de: 'Ein eigennütziger Postbote und ein eigenbrötlerischer Spielzeugmacher freunden sich an und bescheren einem kalten, dunklen Dorf die Freude, die es so bitter nötig hat.',
    description_ja: '自己中な郵便配達員と人を寄せ付けないおもちゃ職人。この2人がなぜかいっしょに、暗く凍てつく町にオモチャを配達。芽生えた友情は、喜びと奇跡をもたらす。',
    description_pt: 'A amizade improvável entre um carteiro egoísta e um solitário fabricante de brinquedos vai levar alegria e entusiasmo ao lugar mais frio, sombrio e infeliz do mundo.',
