    id: '115', slug: 'demon-slayer-kimetsu-no-yaiba-the-movie-mugen-train', title: 'Demon Slayer -Kimetsu no Yaiba- The Movie: Mugen Train', title_ar: 'قاتل الشياطين: قطار اللانهاية', year: 2020,
    director: 'Haruo Sotozaki', director_ar: 'Haruo Sotozaki',
    cast: ['Natsuki Hanae', 'Akari Kito', 'Hiro Shimono', 'Yoshitsugu Matsuoka', 'Satoshi Hino', 'Takahiro Sakurai'],
    genres: ['animation', 'action', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/h8Rb9gBr48ODIwYUttZNYeMWeUU.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/xPpXYnCWfjkt3zzE0dpCNME1pXF.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=v30H0qj_b9E',
    description_ar: 'قصة فيلم Kimetsu no Yaiba Movie: Mugen Ressha-hen تتمة لاحداث الانمي، حيث يقوم “تانجيرو” و “زينتسو” و“اينوسوكي” بشراء تذاكر لـ“القطار الغير محدود” للبحث عن “رينغوكو كونجيرو” عمود اللهب. بأمل أن لديه بعض المعلومات عن رقصة إلاه النار. يخبرهم “رينغوكو” أنه أُرسل في القطار لقتل شيطان يعتقد أنه يسكن بداخله، وأنه لا يعرف شيئًا عن رقصة إلاه النار. سرعان ما أحس بالشيطان وقتله، لتطلب المجموعة التي أعجبت بمهاراته، أن يجعلهم “تسوغوكو” و“رينغوكو” خاص به.',
    description_en: 'Tanjiro Kamado, joined with Inosuke Hashibira, a boy raised by boars who wears a boar\'s head, and Zenitsu Agatsuma, a scared boy who reveals his true power when he sleeps, boards the Infinity Train on a new mission with the Fire Hashira, Kyojuro Rengoku, to defeat a demon who has been tormenting the people and killing the demon slayers who oppose it!',
    description_fr: 'Le groupe de Tanjirô a terminé son entraînement de récupération au domaine des papillons et embarque à présent en vue de sa prochaine mission à bord du train de l\'infini, d\'où quarante personnes ont disparu en peu de temps. Tanjirô et Nezuko, accompagnés de Zen\'itsu et Inosuke, s\'allient à l\'un des plus puissants épéistes de l\'armée des pourfendeurs de démons, le Pilier de la Flamme Kyôjurô Rengoku, afin de contrer le démon qui a engagé le train de l\'Infini sur une voie funeste.',
    description_es: 'Tanjiro y sus compañeros se unen al Pilar de las Llamas Kyojuro Rengoku para investigar una misteriosa serie de desapariciones que han ocurrido dentro del “Tren Infinito”. Poco saben que Enmu, uno de los miembros de las Doce Lunas Demoníacas, también está a bordo y les ha preparado una trampa.',
    description_tr: 'Film ailesi acımasızca öldürülen Tanjiro Kamado\'nun hikayesini anlatıyor.Tanjiro Kamado, ailesi acımasızca öldürüp, kız kardeşinin bir çeşit iblise dönüştürülmesinden sonra, iblis avcılığına başlar. Tanjiro ve arkadaşları, umutsuzluğa çıkan yolda Mugen Treni\'nin peşine düşer.',
    description_de: 'Tanjirō und seine Gefährten haben ihr Rehabilitationstraining im Schmetterlingsanwesen abgeschlossen und erreichen den Ort ihrer nächsten Mission. Im »Mugen-Zug« sind über 40 Leute innerhalb kürzester Zeit verschwunden. Tanjirō, Nezuko, Zenitsu und Inosuke schließen sich einem der mächtigsten Schwertkämpfer unter den Dämonenjägern an: der Säule der Flammen Kyōjurō Rengoku. Zusammen wollen sie sich dem Dämon stellen, der im »Mugen-Zug« lauert und begeben sich auf eine Fahrt in die Dunkelheit.',
    description_ja: '蝶屋敷での修業を終えた炭治郎たちは、次なる任務の地、《無限列車》に到着する。 そこでは、短期間のうちに四十人以上もの人が行方不明になっているという。 禰豆子を連れた炭治郎と善逸、伊之助の一行は、 鬼殺隊最強の剣士である《柱》のひとり、炎柱の煉獄杏寿郎と合流し、 闇を往く《無限列車》の中で、鬼と立ち向かうのだった。',
    description_pt: 'Tanjirou e seus amigos juntam-se ao Pilar de Chamas Kyojuro Rengoku para enfrentar o demónio a bordo do Comboio Infinito, com destino ao desespero. Depois de completar o treino na Casa da Borboleta, Tanjirou e seus amigos seguem para a próxima missão, o Comboio Infinito, onde mais de 40 pessoas desapareceram num período muito curto de tempo. Tanjirou e Nezuko, acompanhados por Zenitsu e Inosuke, juntam-se a um dos mais poderosos espadachins entre os membros Caçadores de Demónios, o atual Pilar de Chamas Kyojuro Rengoku, com o objetivo de enfrentar o demónio a bordo do Comboio Infinito. O que eles não sabem é que estão a cair numa armadilha mortal montada por Enmu, o Demónio do Sonho e um dos 12 Demónios da Lua, num comboio com destino ao desespero...',
    rating_overall: 8.3, rating_story: 8.3, rating_acting: 8.4, rating_direction: 8.2, rating_cinematography: 8, rating_music: 7.8,
    imdb_rating: 8.2, rotten_tomatoes: 82,
