    id: '122', slug: 'scarface', title: 'Scarface', title_ar: 'الوجه ذو الندبة', year: 1983,
    director: 'Brian De Palma', director_ar: 'Brian De Palma',
    cast: ['Al Pacino', 'Steven Bauer', 'Michelle Pfeiffer', 'Mary Elizabeth Mastrantonio', 'Robert Loggia', 'Miriam Colon'],
    genres: ['action', 'crime', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/iQ5ztdjvteGeboxtmRdXEChJOHh.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/1qM2BYNE11Viby8ImC9LC00DgDr.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=lZMIrD36MG8',
    description_ar: 'بعد حصوله على البطاقة الخضراء مقابل اغتيال مسؤول حكومي كوبي ، يطالب توني مونتانا بتجارة المخدرات في ميامي. يقتل توني بوحشية أي شخص يقف في طريقه ، ويصبح في النهاية أكبر أباطرة مخدرات في الولاية ، حيث يتحكم تقريبًا في كل الكوكايين الذي يأتي عبر ميامي. لكن الضغط المتزايد من الشرطة والحروب مع عصابات المخدرات الكولومبية والبارانويا التي تغذيها المخدرات تعمل على تأجيج نيران سقوطه في نهاية المطاف.',
    description_en: 'After getting a green card in exchange for assassinating a Cuban government official, Tony Montana stakes a claim on the drug trade in Miami. Viciously murdering anyone who stands in his way, Tony eventually becomes the biggest drug lord in the state, controlling nearly all the cocaine that comes through Miami. But increased pressure from the police, wars with Colombian drug cartels and his own drug-fueled paranoia serve to fuel the flames of his eventual downfall.',
    description_fr: 'En 1980, le gouvernement cubain expulse plusieurs centaines de prisonniers dangereux vers la Floride. Parmi eux, Tony Montana : ambitieux et sans scrupules, il élabore un plan pour prendre la place d\'un caïd de la drogue.',
    description_es: 'Un emigrante cubano frío y sanguinario, Tony Montana, llega de Cuba para instalarse en Miami, donde se propone hacerse con un nombre dentro del crimen organizado de Florida. Junto a su amigo, Manny Rivera, inicia una ascendente carrera delictiva.',
    description_tr: 'Tony Montana isimli Kübalı suçlu, Miami\'ye gelip uyuşturucu lordu Robert Loggia\'nın emrinde çalışmaya başlar. Montana\'nın hırsı ve öfkesi basamaklaı hızla tırmanıp büyük bir suç şebekesinin başı olmasını sağlar. Film, uyuşturucu dünyasının gizli kapılar ardında dönen çarklarından başlayarak suç dünyasını gözler önüne serer.',
    description_de: '1980 wandert der politisch verfolgte Kubaner Tony Montana nach Florida in den USA aus. Bald wird er seinem Job als Tellerwäscher überdrüssig und beteiligt sich an einem Kokainschmuggel. Der mächtige Drogenhändler Alejandro Sosa findet Gefallen an dem zielstrebigen Kubaner und integriert ihn in seine dunklen Machenschaften. Mit starkem Willen und kompromisslosem Handeln bahnt sich Tony Montana schnell den Weg an die Spitze. Als er jedoch dem Größenwahn verfällt, fühlt sich Sosa bedroht und möchte Montana beseitigen lassen.',
    description_ja: '1980年春、キューバから何千もの人間が自由を求めてアメリカを目指した。その中に、太陽が降り注ぐマイアミに一攫千金を夢見る男がいた。彼の名は、トニー・モンタナ。彼の野望と情熱は、白い粉’コカイン’の一大大国を築き上げていくこと。無一文から暗黒街のボスにのし上がっていくが、頂点に上り詰めた彼を待ち受けた末路とは・・・。',
    description_pt: 'Al Pacino oferece-nos uma inesquecível interpretação como Tony Montana, um dos grangsters mais duros alguma vez representado em filme, neste crime épico inspirado no clássico de 1932 com o mesmo nome.  Realizado pelo criador de sucessos Brian de Palma e produzido por Martin Bregman, que levou ao ecrã ambas as lendas de O Padrinho, Scarface A Força do Poder segue a carreira violenta de um refugiado Cubano que abre caminho até ao comando do império da cocaína em Miami.  Com o seu intenso argumento da autoria do vencedor do Óscar® da Academia – Oliver Stone, com uma orquestração musical conduzida por Giorgio Moroder e uma capacidade soberba de captar o bom estilo Latino de Miami, Scarface A Força do Poder entra para a categoria dos melhores dramas de Hollywood sobre o submundo das drogas.',
    rating_overall: 8.3, rating_story: 8.3, rating_acting: 8.4, rating_direction: 8.2, rating_cinematography: 8, rating_music: 7.8,
    imdb_rating: 8.2, rotten_tomatoes: 82,
    budget_million: 25.0,
    box_office_million: 66,
    duration: 170, language: 'EN', country: 'US',
    reviews_count: 3946, is_featured: false, release_date: '1983-12-09', tags: ['action', 'crime', 'drama', '1983', 'palma'],
