    id: '123', slug: 'the-seventh-seal', title: 'The Seventh Seal', title_ar: 'Det sjunde inseglet', year: 1957,
    director: 'Ingmar Bergman', director_ar: 'Ingmar Bergman',
    cast: ['Gunnar Björnstrand', 'Bengt Ekerot', 'Nils Poppe', 'Max von Sydow', 'Bibi Andersson', 'Inga Gill'],
    genres: ['drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/wcZ21zrOsy0b52AfAF50XpTiv75.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/6s2BqtDvp1BMiP70zCDU5OW6hMy.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=vZucwtdSvJ8',
    description_ar: 'عندما عاد الفارس السويدي أنطونيوس بلوك المحبط إلى وطنه من الحروب الصليبية ليجد بلده في قبضة الموت الأسود ، يتحدى الموت في مباراة شطرنج طوال حياته. بعد تعذيبه بالاعتقاد بأن الله غير موجود ، ينطلق Block في رحلة ، حيث يلتقي باللاعبين المسافرين جوف وزوجته ميا ، ويصبح مصمماً على التهرب من الموت لفترة كافية لارتكاب فعل تعويضي واحد بينما لا يزال على قيد الحياة.',
    description_en: 'When disillusioned Swedish knight Antonius Block returns home from the Crusades to find his country in the grips of the Black Death, he challenges Death to a chess match for his life. Tormented by the belief that God does not exist, Block sets off on a journey, meeting up with traveling players Jof and his wife, Mia, and becoming determined to evade Death long enough to commit one redemptive act while he still lives.',
    description_fr: 'Au XIVe siècle, la grande peste ravage la Suède. De retour des croisades, le chevalier Antonius Blok rencontre la Mort sur son chemin. Espérant retarder l\'échéance fatidique, le temps de trouver des réponses à ses questionnements métaphysiques, il lui propose une partie d\'échecs. Sur la route, tandis que l\'écuyer qui l\'accompagne professe sa philosophie nihiliste, les deux hommes rencontrent le bateleur Jof qui chemine avec sa jeune famille au cœur du pays tourmenté et dit avoir vu la vierge Marie.',
    description_es: 'Suecia, mediados del siglo XIV. La Peste Negra asola Europa. Tras diez años de inútiles combates en las Cruzadas, el caballero sueco Antonius Blovk y su leal escudero regresan de Tierra Santa. Blovk es un hombre atormentado y lleno de dudas. En el camino se encuentra con la Muerte que lo reclama. Entonces él le propone jugar una partida de ajedrez, con la esperanza de obtener de Ella respuestas a las grandes cuestiones de la vida: la muerte y la existencia de Dios.',
    description_tr: 'Ortaçağ\'da Haçlı Seferleri\'nden dönen bir şövalye savaşlar sırasında hep ölümle burun buruna gelse de, hayatta kalmayı başarmıştır. Ancak tam huzura kavuşacağını düşünürken, karşısına onun hayatını almaya gelmiş olan ölüm çıkar. Ölümle pazarlığa oturan savaşçı, onu bir satranç oyununa davet eder. Yolculuğu sırasında kendisine eşlik eden ölümle bir taraftan oyun oynayan şövalye, yol boyunca çok farklı insanlara ve durumlara tanık olacaktır.',
    description_de: 'Mitte des 14. Jahrhunderts durchstreift die Pest ganz Europa. Der Ritter Antonius Block ist als junger Mann hinaus in das Heilige Land gezogen, um seinen Glauben zu festigen. Er kehrt in seine Heimat Schweden zurück, da ihn Zweifel an der Existenz Gottes quälen. Der Schwarze Tod hat auch dort Angst und Schrecken verbreitet. Der personifizierte Tod steht ihm gegenüber. Antonius Block bittet um Aufschub und schlägt ihm eine Partie Schach vor, die die Entscheidung über sein junges Leben fällen soll. Bevor er sterben muss, möchte der Ritter noch eine bedeutende Tat vollbringen: Eine herumziehende Schauspielerfamilie, die inmitten aller Leiden ihre Lebensfreude bewahrt hat, möchte er retten.',
    description_ja: 'ペストが流行し終末的様相を呈した中世ヨーロッパ、10年に及ぶ十字軍遠征から帰還し疲弊し切った騎士アントーニウス（マックス・フォン・シドー）の前に死神（ベント・エーケロート）が出現する。死の宣告を悟った彼は、自らの命を懸けチェス対決を申し出るが、夜が明け死神は姿を消す。故郷を目指すアントーニウスの旅には常に死の気配がつきまとい、残酷な現実が待ち受けていた……。  名だたる映画作家たちに多大な影響を与え続けるスウェーデンの巨匠イングマール・ベルイマンが、人間の生と死、神の存在をテーマにした異色作。終末的様相を呈した中世ヨーロッパを舞台に、十字軍遠征から帰還し生きる意味や信仰に懐疑的になり、死神にとりつかれた騎士の姿を幻想的な映像で描く。',
    description_pt: 'De volta das Cruzadas, um cavaleiro vê o seu país espiritual e fisicamente devastado. Com a fé abalada e o sentido da vida a tomar de assalto o seu pensamento, este é abordado por uma estranha e enigmática personagem: a Morte. Pronta para levar o homem consigo, a Morte é desafiada para um jogo de xadrez, cujo resultado ditará o destino do cavaleiro.',
    rating_overall: 8.2, rating_story: 8.3, rating_acting: 8.4, rating_direction: 8.2, rating_cinematography: 8, rating_music: 7.8,
    imdb_rating: 8.2, rotten_tomatoes: 82,
    budget_million: 0.1,
    box_office_million: 0,
    duration: 96, language: 'SV', country: 'SE',
    reviews_count: 2820, is_featured: false, release_date: '1957-02-16', tags: ['fantasy', 'drama', '1957', 'bergman'],
    pros_ar: ['عمق درامي استثنائي', 'أداء تمثيلي رائع', 'قصة إنسانية مؤثرة'],
    cons_ar: ['وتيرة بطيئة في بعض المشاهد', 'يحتاج تركيزاً عالياً'],
