    id: '124', slug: 'bound-by-honor', title: 'Bound by Honor', title_ar: 'Bound by Honor', year: 1993,
    director: 'Taylor Hackford', director_ar: 'Taylor Hackford',
    cast: ['Damian Chapa', 'Jesse Borrego', 'Benjamin Bratt', 'Enrique Castillo', 'Victor Rivers', 'Delroy Lindo'],
    genres: ['crime', 'drama', 'thriller'],
    poster_url: 'https://image.tmdb.org/t/p/w500/gvP6R6juhe2IpCG7QGDgjyUvm0g.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/9xjUZjuYyehv2qnqMH0oR9nSTft.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=NMj89zgI8Yc',
    description_ar: 'Based on the true life experiences of poet Jimmy Santiago Baca, the film focuses on half-brothers Paco and Cruz, and their bi-racial cousin Miklo. It opens in 1972, as the three are members of an East L.A. gang known as the "Vatos Locos", and the story focuses on how a violent crime and the influence of narcotics alter their lives. Miklo is incarcerated and sent to San Quentin, where he makes a "home" for himself. Cruz becomes an exceptional artist, but a heroin addiction overcomes him with tragic results. Paco becomes a cop and an enemy to his "carnal", Miklo.',
    description_en: 'Based on the true life experiences of poet Jimmy Santiago Baca, the film focuses on half-brothers Paco and Cruz, and their bi-racial cousin Miklo. It opens in 1972, as the three are members of an East L.A. gang known as the "Vatos Locos", and the story focuses on how a violent crime and the influence of narcotics alter their lives. Miklo is incarcerated and sent to San Quentin, where he makes a "home" for himself. Cruz becomes an exceptional artist, but a heroin addiction overcomes him with tragic results. Paco becomes a cop and an enemy to his "carnal", Miklo.',
    description_fr: 'Dans les années 1970, Miklo, issu d\'un métissage américain et mexicain, est en liberté conditionnelle. Lorsqu\'il frappe son père à Las Vegas, il retourne immédiatement dans son quartier d\'origine à East Los Angeles. Il y retrouve sa famille maternelle et mexicaine, dont principalement Paco et Cruzito, ses cousins. Malgré sa peau blanche, Miklo reste un chicano, mais lorsqu\'avant la fin de sa probation il veut son tatouage "Vatos Locos" et que pour cela il doit faire ses preuves, il n\'hésite pas attaquer un gang rival, ce qui va engendrer une guerre et la séparation des trois chicanos.',
    description_es: 'Tres primos crecen como hermanos en medio de la violencia de las bandas del este de Los Ángeles. Con el tiempo sus vidas siguen caminos muy diferentes: uno trabaja para la brigada antidroga de la Policía, otro cae en las redes de las brutales bandas de San Quintín y el tercero se deja arrastrar por el sórdido mundo de la drogadiccion. Pero el sentido del honor y sobre todo los lazos de sangre los mantendrán siempre unidos.',
    description_tr: 'Meksikalı iki kardeş olan Paco ve Cruz ile kuzenleri Miklo’nun 70’lerde Los Angeles’ta katıldıkları sokak çetesinin hayatlarında yarattığı büyük değişimler konu ediliyor. Bu üç adamın 80’lerin ortasına kadarki yaşamları gözler önüne seriliyor. Çetenin şiddet uygulamayı zorunlu kılan birtakım işlerine bulaştıktan ve bu vesileyle hapishaneyle tanıştıktan sonra, tepeden tırnağa değişen karakterlerin her biri farklı yollara sapıyor. Böylece birbirlerine olan bağlılıkları da geçmişteki bir anı olarak kalıyor sadece.',
    description_de: 'US-amerikanischer Kriminalfilm, der die miteinander verwobenen Leben der drei Brüder Miklo, Cruz  und Paco in Chicago ab dem Jahr 1972 bis Mitte der 1980er thematisiert. Miklo ist in den Augen der anderen kein "reiner" Latino und gilt als "Weisser". Als er trotzdem in die Gang aufgenommen wird, ist er sehr stolz. Doch da fangen die Probleme erst an.',
    description_ja: 'Based on the true life experiences of poet Jimmy Santiago Baca, the film focuses on half-brothers Paco and Cruz, and their bi-racial cousin Miklo. It opens in 1972, as the three are members of an East L.A. gang known as the "Vatos Locos", and the story focuses on how a violent crime and the influence of narcotics alter their lives. Miklo is incarcerated and sent to San Quentin, where he makes a "home" for himself. Cruz becomes an exceptional artist, but a heroin addiction overcomes him with tragic results. Paco becomes a cop and an enemy to his "carnal", Miklo.',
    description_pt: 'Based on the true life experiences of poet Jimmy Santiago Baca, the film focuses on half-brothers Paco and Cruz, and their bi-racial cousin Miklo. It opens in 1972, as the three are members of an East L.A. gang known as the "Vatos Locos", and the story focuses on how a violent crime and the influence of narcotics alter their lives. Miklo is incarcerated and sent to San Quentin, where he makes a "home" for himself. Cruz becomes an exceptional artist, but a heroin addiction overcomes him with tragic results. Paco becomes a cop and an enemy to his "carnal", Miklo.',
    rating_overall: 8.2, rating_story: 8.3, rating_acting: 8.4, rating_direction: 8.2, rating_cinematography: 8, rating_music: 7.8,
