    id: '127', slug: 'terminator-2-judgment-day', title: 'Terminator 2: Judgment Day', title_ar: 'المدمر 2  يوم القيامة', year: 1991,
    director: 'James Cameron', director_ar: 'James Cameron',
    cast: ['Arnold Schwarzenegger', 'Linda Hamilton', 'Edward Furlong', 'Robert Patrick', 'Earl Boen', 'Joe Morton'],
    genres: ['action', 'thriller', 'scifi'],
    poster_url: 'https://image.tmdb.org/t/p/w500/jFTVD4XoWQTcg7wdyJKa8PEds5q.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/izkMjmhauFx9DjoBQqM5sM5WAwE.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=CRRlbK5w8AE',
    description_ar: 'مرت ما يقرب من 10 سنوات منذ أن تم استهداف سارة كونور من قبل سايبورغ من المستقبل. الآن ابنها ، جون ، القائد المستقبلي للمقاومة ، هو هدف لمنهي جديد أكثر فتكًا. مرة أخرى ، تمكنت المقاومة من إعادة حاميها في محاولة لإنقاذ جون ووالدته سارة.',
    description_en: 'Ten years after the events of the original, a reprogrammed T-800 is sent back in time to protect young John Connor from the shape-shifting T-1000. Together with his mother Sarah, he fights to stop Skynet from triggering a nuclear apocalypse.',
    description_fr: 'En 2029, après leur échec pour éliminer Sarah Connor, les robots de Skynet programment un nouveau Terminator, le T‐1000, pour retourner dans le passé et éliminer son fils John Connor, futur leader de la résistance humaine. Ce dernier programme un autre cyborg, le T‐800, et l’envoie également en 1995, pour le protéger. Une seule question déterminera le sort de l’humanité : laquelle des deux machines trouvera John la première ?',
    description_es: 'Ha pasado once años desde que Sarah Connor fue marcada como objetivo para ser eliminada por un cyborg del futuro. Ahora su hijo John, el futuro líder de la resistencia, es el objetivo de un Terminator más moderno, más mortífero. Una vez más, la resistencia se las ha ingeniado para enviar un protector de vuelta al pasado para intentar salvar a John y a su madre Sarah.',
    description_tr: 'Sarah Connor\'ın Skynet tarafından gelecekten gönderilen Terminator\'ın elinden kurtulmasından on yıl kadar sonra, 1995 yılında bu kez T-1000 modeli yeni bir Terminator, insan direnişçilerin gelecekteki lideri ve Sarah\'nın oğlu John Connor\'ı öldürmek için 2029 yılından gönderilir. Direnişçiler ise 1995 yılına yeniden programladıkları T-800 modeli bir Terminator göndermeyi başarırlar. T-800\'ün görevi Sarah\'yı akıl hastanesinden kaçırmak ve John\'u T-1000\'e karşı korumaktır.',
    description_de: 'Zehn Jahre nach der Terrorherrschaft des ersten Terminators kehrt ein neuer Killer-Cyborg auf die Erde zurück. Der Auftrag des T-1000 lautet: John Connor muss sterben. Der zwölfjährige John ist der einzige, der eines fernen Tages die Menschheit vor der Übernahme der Weltherrschaft durch die Maschinen retten könnte. Doch die Rebellen aus der Zukunft sind wachsam. Zum Schutz für John entsenden sie einen umprogrammierten Terminator der alten Generation, den T-800, auf die Erde.',
    description_ja: '未来からの抹殺兵器ターミネーターを破壊し、近未来で恐ろしい戦争が起こる事を知ってしまったサラ・コナー。カイルとの子供ジョンは母親から常にその戦争の話や戦いへの備えの話を聞かされていた。サラは周囲から変人扱いされ精神病院へ収容されジョンは親戚の家で暮らしていた。ある日ジョンの前に執拗にジョンを狙う不審な警官が現る。軌道を逸した警官の行動は明らかにジョンを殺害しようとしていた。殺されるその寸前、見知らぬ屈強な男が現れジョンを救う。彼は自らをターミネーターでありジョンを守るべく再プログラムされ未来から送り込まれたと告げる。ジョンは病院の母親を連れ出し、最終戦争を起こす原因であるコンピューターシステム「スカイネット」を破壊するため、ターミネーターと共にサイバーダイン社へ向かうが・・・',
    description_pt: 'Passaram-se quase dez anos desde que a provação de Sarah teve início e o seu filho John, o futuro líder da resistência, é agora um jovem e saudável rapaz. Porém, o pesadelo recomeça, quando um novo e letal exterminador é enviado do futuro. As suas ordens: atacar John Connor enquanto este é ainda uma criança. Contudo, Sarah e John não terão de enfrentar sozinhos este terrível Exterminador. A resistência humana enviou um outro guerreiro do futuro e as suas ordens são proteger John Connor a todo o custo – começou a batalha pelo amanhã...',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 102.0,
    box_office_million: 518,
    duration: 137, language: 'EN', country: 'FR',
    reviews_count: 3380, is_featured: false, release_date: '1991-07-03', tags: ['action', 'thriller', 'science-fiction', '1991', 'cameron'],
    pros_ar: ['إثارة وأكشن مبهر', 'مؤثرات بصرية رائعة', 'إيقاع سريع وممتع'],
    cons_ar: ['وتيرة بطيئة في بعض المشاهد', 'يحتاج تركيزاً عالياً'],
    pros_en: ['Thrilling action sequences', 'Impressive visual effects', 'Fast-paced and exciting'],
    cons_en: ['Slow pacing in some scenes', 'Requires close attention'],
