    id: '130', slug: 'the-kid', title: 'The Kid', title_ar: 'The Kid', year: 1921,
    director: 'Charlie Chaplin', director_ar: 'Charlie Chaplin',
    cast: ['Charlie Chaplin', 'Jackie Coogan', 'Carl Miller', 'Edna Purviance', 'Albert Austin', 'Beulah Bains'],
    genres: ['comedy', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/A9NWYyn7eX0H9XIjaOvfWJ9mCGA.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/mAhCW7QbpL5kwvCWGsfyY3ILoW6.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=O5WXokyub-4',
    description_ar: 'A tramp cares for a boy after he\'s abandoned as a newborn by his mother. Later the mother has a change of heart and aches to be reunited with her son.',
    description_en: 'A tramp cares for a boy after he\'s abandoned as a newborn by his mother. Later the mother has a change of heart and aches to be reunited with her son.',
    description_fr: 'Un vagabond recueille un enfant abandonné par sa jeune mère qui, quelques années plus tard, est prise de remords et tente de retrouver son fils.',
    description_es: 'Una mujer londinense, sumamente pobre, se ve en la necesidad de abandonar a su hijo en una casa de millonarios, aunque por una serie de circustancias el niño terminará siendo cuidado por un vagabundo que se convierte así en su padre. Cinco años después, y con la madre convertida en una popular cantante, el destino tratará de separarlos...',
    description_tr: 'Chaplin klasiklerinden biri daha!  Yapımcılığını üstlendiği ilk uzun metrajlı fiilminde, Tramp’in ve dünyalar tatlısı 6 yaşında bir çocuğun kimi zaman komik kimi zaman gözlerinizde yaşlara sebep olacak hüzünlü hikayesi anlatılıyor. Hikaye Tramp’in terkedilmiş bir bebeği bulması ve onu kurtararak evine almasıyla başlar. Hafızalardan silinmeyecek sahneleri ve Chaplin’in yorumuyla hüzün ve eğlencenin harmanlandığı bu filmi kaçırmayın!',
    description_de: 'Charlie Chaplin ist in der Rolle eines Landstreichers zu sehen, der einem kleinen Kind begegnet und ungeplanter Weise zu seinem Ziehvater wird. Die Mutter des Kleinen ist eine berühmte Schauspielerin und fordert den Jungen schließlich zurück …',
    description_ja: 'ある日、いつもの様に街を散歩していたチャーリーの耳に赤ん坊の泣き声が聞こえてきた。辺りを見回すとまだ生まれたばかりの赤ん坊が街頭に捨てられている。どうしたものかと抱き上げた彼の目の前に、パトロール中の警官が通りかかった。警官は彼が赤ん坊を捨てにきたと勘違いし、目を光らせている。仕方なく彼は、その赤ん坊を自分のボロ・アパートに連れて帰った。それから5年後－－その子はチャーリーの仕事を手伝う程成長していた。',
    description_pt: 'Charlot toma conta de uma criança abandonada, mas a sua relação fica em risco, quando a mãe tenta recuperar a criança. Cópia digital restaurada de um dos mais conhecidos filmes de Charlie Chaplin.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
