    id: '131', slug: 'singin-in-the-rain', title: 'Singin\' in the Rain', title_ar: 'Singin\' in the Rain', year: 1952,
    director: 'Stanley Donen', director_ar: 'Stanley Donen',
    cast: ['Gene Kelly', 'Donald O\'Connor', 'Debbie Reynolds', 'Jean Hagen', 'Millard Mitchell', 'Cyd Charisse'],
    genres: ['comedy', 'romance'],
    poster_url: 'https://image.tmdb.org/t/p/w500/w03EiJVHP8Un77boQeE7hg9DVdU.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/6qOyw4yfzbzTp5YsCX26C28Do0S.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=lSE8sl2-PZg',
    description_ar: 'في عام 1927 ، قامت شركة إنتاج أفلام صامتة وفريق عمل بانتقال صعب إلى الصوت.',
    description_en: 'In 1927 Hollywood, a silent film star falls for a chorus girl just as he and his paranoid screen partner struggle to make the difficult transition to talking pictures.',
    description_fr: 'Les films muets laissent place aux films parlants - et le danseur devenu chanteur est lui aussi pris dans cette transition compliquée, tout comme son ami, sa petite amie et sa désagréable co-star.',
    description_es: 'Antes de conocer a la aspirante a actriz Cathy Seldon, el ídolo del cine mudo Don Lockwood pensaba que lo tenía todo; fama, fortuna y éxito. Pero, tras conocerla, se da cuenta de que ella es lo que realmente faltaba en su vida. Con el nacimiento del cine sonoro, Don quiere filmar los musicales con Kathy, pero entre ambos se interpone la reina del cine mudo Lina Lamont.',
    description_tr: 'Artık sessiz filmlerin dönemi kapanmaktadır ve konuşmaların yeraldığı sesli filmlere geçilirken, ünlü bir sahne yıldızı, en iyi arkadaşı, olası kız arkadaşı ve kurnaz oyuncu arkadaşı  bu zorlu geçiş dönemine yakalanmışlardır.',
    description_de: 'In den späten zwanziger Jahren versuchen die beiden Freunde Don Lockwood und Cosmo Brown, ihr Glück in Hollywood zu machen. Zusammen mit seiner Partnerin, der hysterischen Schauspielerin Lina Lamont, hat Don schnell großen Erfolg. Als die Zeit der Umstellung vom Stumm- zum Tonfilm kommt, werden Linas Karriere und eine laufende Produktion durch ihre dünne, hohe Stimme gefährdet. Cosmo rettet das Projekt durch die Idee, aus dem Film ein Musical zu machen und Lina von Dons Freundin Kathy nachsynchronisieren zu lassen.',
    description_ja: '多数の映画で共演を続けてきたドンとリーナは、世間から結婚まで噂される人気のスターカップル。しかし実はリーナのわがままな態度にドンは辟易気味。やがて撮影中の新作がサイレントからトーキーへと製作方針を変え、ドンは声質がよくないリーナに代わって、知り合ったばかりであるコーラスガール、キャシーに歌の吹き替えを頼む。出来あがった映画は大好評だが、意地悪なリーナはその手柄を独り占めしようとする。',
    description_pt: 'Don Lockwood e Lina Lamont são dois dos astros mais famosos do cinema mudo em Hollywood e as revistas apostam num relacionamento mais íntimo entre eles. Mas a chegada do cinema falado vai ameaçá-los com o esquecimento. Decididos a produzir um filme falado, Don e Lina têm de superar as dificuldades do novo método de fazer cinema para conseguir manter a fama.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 2.5,
    box_office_million: 7,
