    id: '132', slug: 'central-station', title: 'Central Station', title_ar: 'Central do Brasil', year: 1998,
    director: 'Walter Salles', director_ar: 'Walter Salles',
    cast: ['Fernanda Montenegro', 'Vinícius de Oliveira', 'Marília Pêra', 'Othon Bastos', 'Otávio Augusto', 'Matheus Nachtergaele'],
    genres: ['drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/zJvp7XjQ2LhPbDVYhFXyucs40vR.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/lrLIy9OFRQg4VkhrCyolfNXJEUH.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=qCoqppCsEa8',
    description_ar: 'An emotional journey of a former school teacher, who writes letters for illiterate people, and a young boy, whose mother has just died, as they search for the father he never knew.',
    description_en: 'An emotional journey of a former school teacher, who writes letters for illiterate people, and a young boy, whose mother has just died, as they search for the father he never knew.',
    description_fr: 'Dora, ex-institutrice, gagne sa vie en écrivant des lettres pour les migrants illettrés à la gare centrale de Rio. Ana et son jeune fils Josue font appel à ses services pour retrouver le père de Josue. Lorsque Dora rentre dans son petit appartement de banlieue, elle fait le tri des lettres de la journée, en envoie certaines, jette les autres et en garde une partie dans un tiroir. C\'est ce qui arrive à la lettre de Josue. Quand sa mère meurt, renversée par un bus, Josue demande à Dora de l\'aider à retrouver son père. D\'abord insensible, Dora finit par accepter de l\'aider.',
    description_es: 'En los asfixiantes pasillos de la Estación Central, en Río de Janeiro, una antigua maestra se gana la vida escribiendo las cartas que le dictan los analfabetos. Endurecida por la soledad y por la adversidad, Dora ha ido cayendo en una estoica indiferencia. Sin embargo, cuando una de sus clientes muere atropellada a la salida de la estación, decide hacerse cargo de su hijo y llevarlo a casa de su padre en una remota zona del nordeste de Brasil.',
    description_tr: 'Rio de Janeiro\'da çalışan, müşterilere mektup yazıp postalamakla görevli soğuk ve yaşlı bir kadın olan Dora (Fernanda Montenegro), müşterilerden ve insanlardan nefret ediyor. Dokuz yaşında bir çocuk olan Josue (Vinicius de Oliveira), babasını hiç görmemiş. Josue\'nun annesi, kocasına mektuplar yazıyor ve bu mektuplar Dora aracılığıyla gönderiliyor. Kadın bir araba kazasında ölünce, Josue\'nin sorumluluğunu insanları pislik olarak gören Dora üstlenmek zorunda kalıyor. Dora, Josue\'yı babasını görebilmesi için yolculuğa çıkmaya ikna ediyor ve bu iki farklı insan arasında sıradışı bir dostluk kuruluyor.',
    description_de: 'Central do Brasil ist ein brasilianischer Klassiker von Regisseur Walter Salles über die Beziehung einer älteren verbitterten Frau zu einem verwaisten Jungen, der in Rio de Janeiro spielt. Central do Station meint den Hauptbahnhof der Metropole.',
    description_ja: 'かつて教師をしていたドーラは、今はリオデジャネイロの中央駅で代筆業を営んでいる。字の書けない人のために手紙を書くのが彼女の仕事だが、次第に何の感情も持たないようになり、その手紙を実際に出すことはほとんどなくなっていた。',
    description_pt: 'Dora trabalha escrevendo cartas para analfabetos na estação Central do Brasil, Rio de Janeiro. A escrivã ajuda um menino, após a sua mãe ser atropelada, a tentar encontrar o pai que nunca conheceu, no interior do Nordeste.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 2.9,
    box_office_million: 6,
    duration: 111, language: 'PT', country: 'BR',
    reviews_count: 2669, is_featured: false, release_date: '1998-04-03', tags: ['drama', '1998', 'salles'],
    pros_ar: ['عمق درامي استثنائي', 'أداء تمثيلي رائع', 'قصة إنسانية مؤثرة'],
    cons_ar: ['وتيرة بطيئة في بعض المشاهد', 'يحتاج تركيزاً عالياً'],
    pros_en: ['Exceptional dramatic depth', 'Outstanding performances', 'Emotionally powerful story'],
    cons_en: ['Slow pacing in some scenes', 'Requires close attention'],
