    id: '135', slug: 'taxi-driver', title: 'Taxi Driver', title_ar: 'سائق التاكسي', year: 1976,
    director: 'Martin Scorsese', director_ar: 'Martin Scorsese',
    cast: ['Robert De Niro', 'Jodie Foster', 'Cybill Shepherd', 'Harvey Keitel', 'Peter Boyle', 'Leonard Harris'],
    genres: ['crime', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/ekstpH614fwDX8DUln1a2Opz0N8.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/9uddYYTNcLWpzUkl5iw1RUYhLhY.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=zdqCqDSTVNI',
    description_ar: 'سائق التاكسي (بالإنجليزية: Taxi Driver)‏ هو فيلم دراما وقصة صدر في 1976 من إخراج مارتن سكورسيزي ومن بطولة روبيرت دي نيرو وجودي فوستر. تدور قصة الفيلم حول ترافيس بيكل (روبيرت دي نيرو) سائق التاكسي وجندي سابق في البحرية خلال حرب فيتنام، يريد تنقية مدينته من الفساد الذي انتشر فيها وبثورة غاضبة منه لا يتبقى أحد من هؤلاء الذي يشعر بأنهم هم السبب في هذا الفساد.',
    description_en: 'Suffering from insomnia, disturbed loner Travis Bickle takes a job as a New York City cabbie, haunting the streets nightly, growing increasingly detached from reality as he dreams of cleaning up the filthy city.',
    description_fr: 'Vétéran de la Guerre du Vietnam, Travis Bickle est chauffeur de taxi dans la ville de New York. Ses rencontres nocturnes et la violence quotidienne dont il est témoin lui font peu à peu perdre la tête. Il se charge bientôt de délivrer une prostituée mineure de ses souteneurs.',
    description_es: 'Para sobrellevar el insomnio crónico que sufre después de su regreso de Vietnam, Travis decide trabajar como taxista nocturno. Como individuo tiene poco contacto con la gente, pero observa la violencia y desolación en la que se hunde la ciudad de Nueva York. Travis anota en su diario todas sus impresiones, hasta que un día decide pasar a la acción.',
    description_tr: 'Hem Martin Scorsese’nin hem de Robert De Niro’nun filmografilerindeki belki de bu en çarpıcı filmde, 70’lerin Manhattan gecelerinde taksicilik yapan Vietnam gazisi Travis’le birlikte sokaklardayız.Hikaye boyunca etrafındaki hayatla ve yolunun kesişeceği "toplumun pisliğiyle" (bir çocuk fahişe, güzel bir sarışın, başkan adayı bir senatör, gözü dönmüş bir kadın satıcısı) bir türlü iletişim kuramayacak olan Travis, en nihayetinde ipleri eline alacaktır. Üstelik gündüzleri izlemeye gittiği belden aşağı filmlerdeki "vahşi" bir stilde...Sadece eşsiz senaryosu ve oyunculuklarıyla değil, sıradışı sinematografisiyle de tüm zamanların en etkili filmlerinden biri...',
    description_de: 'Travis Bickle ist ein Außenseiter. Nicht zuletzt durch seinen Beruf als Taxifahrer lernt der Vietnamveteran die Gesellschaft zu hassen. Die Leere und Kälte, die von den Menschen um ihn herum auszugehen scheint, bringen ihn dazu sich Waffen zu besorgen und für den Kampf gegen den Rest der Welt zu wappnen. Beinahe per Zufall wählt er eine junge Prostituierte aus und nimmt sich ihrer an. Sein Ziel ist es, sie aus ihren Leiden zu befreien. Als er schließlich merkt, dass sie nichteinmal zu realisieren scheint unter welchen Umständen sie lebt, läuft er Amok...',
    description_ja: 'ニューヨークの夜を走るひとりのタクシードライバーを主人公に、現代都市に潜む狂気と混乱を描き出した、監督マーティン・スコセッシ×主演ロバート・デ・ニーロの、アメリカン・ニューシネマの傑作。ベトナム帰りの青年トラヴィス・ビックルは夜の街をタクシーで流しながら、世界の不浄さに苛立ちを感じていた。大統領候補の選挙事務所に勤めるベッツィと親しくなるトラヴィスだったが、彼女をポルノ映画館に誘ったことで絶交されてしまう。やがて、闇ルートから銃を手に入れたトラヴィスは自己鍛錬を始めるが、そんな彼の胸中にひとつの計画が沸き上がる……。',
    description_pt: 'Travis Bickle, um veterano da guerra do Vietname, conduz um táxi em Nova Iorque no turno da noite. Solitário e com insónias, Travis passa a noite a trabalhar, testemunhando a vida sórdida das ruas. Após sucessivas frustações, que incluem um encontro falhado e a tentativa de libertar uma prostituta de catorze anos, Travis, numa mistura de revolta e impotência, decide comprar quatro armas e parte numa cruzada violenta pela cidade...',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 1.9,
    box_office_million: 29,
