    id: '136', slug: 'togo', title: 'Togo', title_ar: 'Togo', year: 2019,
    director: 'Ericson Core', director_ar: 'Ericson Core',
    cast: ['Willem Dafoe', 'Julianne Nicholson', 'Christopher Heyerdahl', 'Richard Dormer', 'Adrien Dorval', 'Madeline Wickins'],
    genres: ['adventure', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/921q4gPNN4J6UxvKaw6SCNBe3F8.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/2Jr2OBzoLLOYqQWnyN4eicZv0sL.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=HMfyueM-ZBQ',
    description_ar: 'القصة الحقيقية غير المروية.  تدور أحداث القصة الحقيقية غير المروية في شتاء عام 1925 والتي تأخذك عبر التضاريس الغادرة لتندرا ألاسكا لمغامرة مبهجة وراقية ستختبر قوة وشجاعة وتصميم رجل واحد ، ليونارد سيبالا ، وكلبه الرئيسي للزلاجة ، توغو.',
    description_en: 'The untold true story set in the winter of 1925 that takes you across the treacherous terrain of the Alaskan tundra for an exhilarating and uplifting adventure that will test the strength, courage and determination of one man, Leonhard Seppala, and his lead sled dog, Togo.',
    description_fr: 'Quand une épidémie de diphtérie ravage un village isolé d\'Alaska durant l\'hiver 1925, rendant gravement malades d\'innombrables enfants, la population est en émoi car l\'antitoxine nécessaire à leur guérison se trouve à des centaines de kilomètres de là, au-devant de terrains difficiles à traverser et alors qu\'une tempête gigantesque se profile à l\'horizon. Les responsables du village s\'en remettent alors au seul homme capable de les sauver, Leonhard Seppala, accompagné de son chien de traîneau, Togo.',
    description_es: '\'Togo\' es la historia real no contada ambientada en el invierno de 1925 de un periplo por el terreno traicionero de la tundra de Alaska en busca de una aventura emocionante que pondrá a prueba la fuerza, el coraje y la determinación de un hombre, Leonhard Seppala, y de su perro de trineo guía, Togo.',
    description_tr: 'Alaska\'da bir kasaba olan Nome\'da ölümcül bir salgın başlar. Salgının tek çaresi 600 milden daha uzak olan bir yerdedir. Kasaba halkı, köpek ve kurt eğitmeni Leonhard Seppala\'dan serumu getirmesi için yardım ister. Seppala, cılız görünümlü ve yaşlı bir Sibirya kurdu olan Togo\'yu liderlik etmesi için yanında götürür. Seppala\'nın eşi Constance, Togo\'yu yavru olduğu dönemden beri tanıyordur ve onun her koşulda cesaret ve sadakat gösterebileceğini biliyordur. Seppala ve Togo yoldayken korkunç bir fırtınayla karşı karşıya kalırlar. -70 dereceye varan soğukta Togo ve Seppala büyük bir yaşam mücadelesi verecektir.',
    description_de: '1925: Die Stadt Nome in Alaska leidet unter einer Krankheitswelle. Um wichtige Medikamente in die Stadt zu bekommen, werden Hundeschlitten auf eine fast 700 Meilen lange Reise geschickt, darunter der Hund Togo und sein Besitzer Leonhard Seppala (Willem Dafoe).',
    description_ja: '1925年、アラスカで実際に起きた、命がけで血清を届ける犬ぞりリレーの“ノーム血清走行”をベースにした実話映画',
    description_pt: '"Togo" é a verdadeira história passada no inverno de 1925 que nos leva por terrenos traiçoeiros da tundra do Alasca, numa aventura emocionante e inspiradora, que vai testar a  resistência, coragem e determinação de um homem, Leonhard Seppala e o seu cão-líder, Togo. Quando uma epidemia mortal ataca a cidade de Nome no Alasca e a única cura está a mais de mil quilómetros de distância, a cidade pede ajuda ao campeão treinador de cães Leonhard Seppala (Willem Dafoe) para ajudar no transporte do soro. Seppala recorre a Togo, um husky siberiano modesto, pequeno e velho para ser o líder. Sem medo da tempestade enorme que se aproxima nem da pressão da mulher que lhe pede para não ir, Seppala e Togo percorrem o trilho mais perigoso de um percurso de trocas, que envolve inúmeros mushers, enfrentando rajadas de ventos fortes, temperaturas de 60 graus negativos e quase nenhuma visibilidade.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    duration: 113, language: 'EN', country: 'US',
    reviews_count: 4241, is_featured: false, release_date: '2019-12-20', tags: ['adventure', 'family', '2019', 'core'],
    pros_ar: ['إخراج متميز', 'قصة مشوقة', 'أداء رائع للممثلين'],
