    id: '137', slug: 'dr-strangelove-or-how-i-learned-to-stop-worrying-and-love-th', title: 'Dr. Strangelove or: How I Learned to Stop Worrying and Love the Bomb', title_ar: 'دكتور سترينجلوف أو: كيف توقفت عن القلق وأحببت القنبلة', year: 1964,
    director: 'Stanley Kubrick', director_ar: 'Stanley Kubrick',
    cast: ['Peter Sellers', 'George C. Scott', 'Sterling Hayden', 'Keenan Wynn', 'Slim Pickens', 'Peter Bull'],
    genres: ['comedy', 'history'],
    poster_url: 'https://image.tmdb.org/t/p/w500/6x7MzQ6BOMlRzam1StcmPO9v61g.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/7i0L2ee4Iy0aXV6vR5u1ZmblOrx.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=Ja3n2Mxf21s',
    description_ar: 'بعد أن بدأ الجنرال المجنون جاك دي ريبر ضربة نووية على الاتحاد السوفيتي ، حاولت غرفة حرب مليئة بالسياسيين والجنرالات والدبلوماسي الروسي جميعًا بشكل محموم وقف الضربة النووية.',
    description_en: 'After the insane General Jack D. Ripper initiates a nuclear strike on the Soviet Union, a war room full of politicians, generals and a Russian diplomat all frantically try to stop it.',
    description_fr: 'Le général Jack Ripper, convaincu que les Russes ont décidé d\'empoisonner l\'eau potable des États-Unis, lance sur l\'URSS une offensive de bombardiers B-52 en ayant pris soin d\'isoler la base aérienne de Burpelson du reste du monde. Pendant ce temps, Muffley, le Président des États-Unis, convoque l\'état-major militaire dans la salle d\'opérations du Pentagone et tente de rétablir la situation.',
    description_es: 'Convencido de que los comunistas están contaminando los Estados Unidos, un general ordena, en un acceso de locura, un ataque aéreo nuclear sorpresa contra la Unión Soviética. Su ayudante, el capitán Mandrake, trata de encontrar la fórmula para impedir el bombardeo. Por su parte, el presidente de los EE.UU. se pone en contacto con Moscú para convencer al gobierno soviético de que el ataque no es más que un estúpido error. Mientras tanto, el asesor estadounidense, un antiguo científico nazi, el doctor Strangelove, confirma la existencia de la «Máquina del Juicio Final», un dispositivo de represalia soviético capaz de acabar con la humanidad para siempre.',
    description_tr: 'Soğuk Savaş döneminde Ruslara saldırmak için bahane aramakta olan çılgın general Jack D. Ripper, Rusların \'Amerikan halkının vücut sıvılarını kirlettiği\' gerekçesiyle SSCB\'ye sürpriz bir nükleer saldırı yapmaya karar verir. Nükleer silahlarla yüklü bir Amerikan uçağı Rus sınırına yakın bir bölgede Soğuk Savaş döneminin tipik devriye uçuşlarından birini yapmaktayken mürettebat Ripper\'dan SSCB\'ye saldırı emrini alır. Fakat Rus büyükelçisi DeSadesky, Amerikan makamlarına Rus savunma teknolojisinin geldiği son noktanın ürünü olan \'Doomsday Device\'dan bahsettiğinde ve başkanın danışmanlarından eski Nazi bilimadamı Dr. Strangelove, buluşun olduğunu doğruladığında durum daha da tehlikeli bir hal alır. \'Doomsday Device\', SSCB\'ye yapılacak herhangi bir nükleer saldırıda dünyadaki tüm canlıların yok olmasına sebep olacak bir silahtır.',
    description_de: 'Ein geisteskranker amerikanischer General, Jack D. Ripper, fühlt sich durch die kommunistische Weltverschwörung mehr und mehr bedroht. Eines Tages dreht er völlig durch. Er setzt die amerikanische Atombombenflotte Richtung Sowjetunion in Marsch. Weil der General das Geheimnis des Rückruf-Codes schließlich mit ins Grab nimmt, ist der amerikanische Präsident Muffley gezwungen, dem Sowjetpremier am Roten Telefon alle Einzelheiten über die anschwebenden Todesbomber zu verraten. Die rote Abwehr kann alle Bomber abschießen – bis auf einen!',
    description_ja: 'アメリカ軍基地の司令官が、ソ連の核基地の爆撃指令を発した。司令官の狂気を知った副官は、司令官を止めようとするが逆に監禁されてしまう。大統領は、ソ連と連絡を取って事態の収拾を図る。しかし、迎撃機によって無線を破壊された1機が、ついに目標に到達してしまう……。',
    description_pt: 'Um general norte-americano louco, Jack D. Ripper, obcecado pelo medo de que os comunistas estejam a sabotar as reservas de água potável dos EUA, resolve lançar vários bombardeiros com armas nucleares contra a Rússia, num ataque sem ordens nem provocação prévia. Informado do incidente, o presidente dos EUA reúne-se no Pentágono com os seus generais e comandantes para evitar o pior, descobrindo que os russos também não têm o controlo completo dos acontecimentos, e que pode ser já tarde demais para evitar o holocausto nuclear.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 1.8,
    box_office_million: 10,
    duration: 95, language: 'EN', country: 'GB',
    reviews_count: 5225, is_featured: false, release_date: '1964-01-29', tags: ['comedy', 'war', '1964', 'kubrick'],
    pros_ar: ['إخراج متميز', 'قصة مشوقة', 'أداء رائع للممثلين'],
    cons_ar: ['وتيرة بطيئة في بعض المشاهد', 'يحتاج تركيزاً عالياً'],
