    id: '138', slug: 'full-metal-jacket', title: 'Full Metal Jacket', title_ar: 'Full Metal Jacket', year: 1987,
    director: 'Stanley Kubrick', director_ar: 'Stanley Kubrick',
    cast: ['Matthew Modine', 'Adam Baldwin', 'Vincent D\'Onofrio', 'R. Lee Ermey', 'Dorian Harewood', 'Kevyn Major Howard'],
    genres: ['drama', 'history'],
    poster_url: 'https://image.tmdb.org/t/p/w500/kMKyx1k8hWWscYFnPbnxxN4Eqo4.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/3k2TRmqMjgt7tcwkYwZQdctnty3.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=n2i917l5RFc',
    description_ar: 'يلاحظ أحد جنود مشاة البحرية الأمريكية الواقعي التأثيرات اللاإنسانية للحرب الأمريكية الفيتنامية على زملائه المجندين من تدريب معسكراتهم الوحشي إلى قتال الشوارع الدموي في هيو.',
    description_en: 'A pragmatic U.S. Marine observes the dehumanizing effects the U.S.-Vietnam War has on his fellow recruits from their brutal boot camp training to the bloody street fighting in Hue.',
    description_fr: 'Pendant la guerre du Vietnam, la préparation et l’entraînement d’un groupe de jeunes marines, jusqu’au terrible baptême du feu et la sanglante offensive du Tết à Hue, en 1968.',
    description_es: 'Un grupo de reclutas se prepara en Parish Island, centro de entrenamiento de la marina Norteamericana. Allí está el sargento Hartmann, duro e implacable, cuya única misión en la vida es endurecer el cuerpo y el alma de los novatos, para que puedan defenderse del enemigo. Pero no todos los jóvenes soportan igual sus métodos...',
    description_tr: 'Yönetmen Stanley Kubrick, Full Metal Jacket filminde savaşın ve askerliğin, insanların duygularını nasıl yok ettiğini gün yüzüne çıkarıyor. 18 yaşındaki acemi bir askerin gözünden, acemi askerlerin Deniz Kuvvetleri\'ndeki ilk günlerinden başlayarak nasıl insani duygularının yok edildiğini ve bireysellikten çıkarılıp Deniz Piyadesi olarak nasıl tekrardan yaratıldıklarını anlatıyor. Film, 1968 yılında Vietnam harekatı için yetiştirilen askerlerin ruhlarında bıraktığı zarar ve savaşın nasıl insanlık dışı bir şey olduğunu açığa çıkartıyor. Gustav Hasford\'un "The Short-Timers" isimli romanından uyarlanmıştır.',
    description_de: 'South Carolina 1967. Im Camp von Parris Island werden Joker und seine Kameraden auf traditionell-brutale Art zu Marines gedrillt. Der Ausbilder bezahlt seine Profiarbeit mit dem Leben: Leonard, sein Lieblingsopfer, erschießt den Schinder, bevor er sich selbst tötet. An der Dschungelfront in Vietnam, nach der Tet-Offensive, geraten Joker – der inzwischen als Journalist Heldenberichte für die Soldatenzeitung „Stars and Stripes“ schreibt – und seine Kameraden in den Hinterhalt eines Heckenschützen. Die scheinbar einfache Wiedereroberung Huếs gerät zum verlustreichen Desaster. Der Scharfschütze, ein Vietcong-Mädchen, wird von den Soldaten getötet. Und der Wahnsinn geht weiter …',
    description_ja: 'スタンリー・キューブリック監督が、G・ハスフォードの原作を基にベトナム戦争の狂気を描く。徴兵された若者が、次第に戦闘マシーンとして人間性を失っていく様を二部構成で描く。  ベトナム戦争の時代、ジェイムズ（愛称ジョーカー）は、サウスカロライナの海兵新兵訓練キャンプ（ブートキャンプ）で、ハートマン軍曹による厳しい訓練を受ける。新兵たちの中で落ちこぼれの「ほほえみデブ」ことレナードは、徹底的なしごきの中で徐々に正気を失っていく…。  新兵訓練を卒業し海兵隊員となったジョーカーは、テト攻勢が始まる中、軍の報道部員としてフエ市街の前線取材を命じられる。だが、交戦の中で小隊長が戦死、分隊長をブービートラップで失う。下士官が指揮を引き継ぎ転進を図るも進路を誤り、今度は狙撃兵の襲撃を受ける。残されたジョーカーは狙撃兵への復讐を図るのだが…。',
    description_pt: 'Um sargento treina de forma fanática e sádica os recrutas numa base americana, na ideia de os tornar em máquinas de guerra para o Vietname. Após serem transformados em fuzileiros, são enviados para a guerra e, quando lá chegam, deparam-se com os seus horrores.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 30.0,
    box_office_million: 46,
