    id: '139', slug: 'palmer', title: 'Palmer', title_ar: 'Palmer', year: 2021,
    director: 'Fisher Stevens', director_ar: 'Fisher Stevens',
    cast: ['Justin Timberlake', 'Ryder Allen', 'Juno Temple', 'Alisha Wainwright', 'June Squibb', 'Dean Winters'],
    genres: ['drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/xSDdRAjxKAGi8fUBLOqSrBhJmF0.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/mlBmnjDJfsAhvqRVc2aFOjsfh8M.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=8jVuOheTNGQ',
    description_ar: 'بعد ١٢ عامًا في السجن، يعود نجم كرة القدم السابق في المدرسة الثانوية Eddie Palmer إلى بيته ليستعيد حياته. يكوّن Eddie علاقة غريبة مع ولد منبوذ من منزل مضطرب، ولكن ماضيه يهدّد حياته الجديدة وعائلته.',
    description_en: 'After 12 years in prison, former high school football star Eddie Palmer returns home to put his life back together—and forms an unlikely bond with Sam, an outcast boy from a troubled home. But Eddie\'s past threatens to ruin his new life and family.',
    description_fr: 'Après 12 ans en prison, l’ex-prodige du football Eddie Palmer revient chez lui pour repartir de zéro. Il se lie d’amitié avec un jeune garçon malmené par la vie, mais son passé trouble menace de réduire en cendres ce nouveau départ.',
    description_es: 'Tras 12 años en prisión, el exjugador de fútbol Palmer vuelve a casa para rehacer su vida. Mientras se adapta a su nueva realidad, entabla una amistad con un niño abandonado, pero su pasado le persigue y amenaza con destruir su nueva familia.',
    description_tr: 'Hapiste geçen 12 yılın ardından hayatına çeki düzen vermek için ninesinin yanına taşınan eski Amerikan futbolu yıldızı Eddie Palmer, sorunlu bir aileden gelen Sam adlı komşu çocuğuyla sıra dışı bir bağ kurar. Fakat Eddie’nin geçmişi yakasını bırakmayacak, yeni ailesiyle hayatını tehlikeye sokacaktır.',
    description_de: 'Nach zwölf Jahren im Gefängnis will Eddie Palmer sein Leben wieder in den Griff bekommen – und freundet sich mit Sam an, einem jungen Außenseiter aus schwierigen Verhältnissen. Doch dann droht Eddies Vergangenheit sein neues Leben zu zerstören.',
    description_ja: '高校時代にフットボール選手として名を馳せたエディー・パーマーは、12年の刑期を終え、人生をやり直すために故郷に帰ってきた。そこで母に見捨てられた少年サムと出会い、思いがけない絆を育むエディー。しかし彼の過去が、新しい生活と家族に暗い影を落とすことになるのだった。',
    description_pt: 'Após 12 anos na prisão, Eddie Palmer regressa a casa para reconstruir a sua vida e cria uma ligação improvável com Sam, um rapaz marginalizado e com uma família problemática. Mas o passado de Edie ameaça arruinar a sua nova vida.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
