    id: '140', slug: 'reservoir-dogs', title: 'Reservoir Dogs', title_ar: 'كلاب المستودع', year: 1992,
    director: 'Quentin Tarantino', director_ar: 'Quentin Tarantino',
    cast: ['Harvey Keitel', 'Tim Roth', 'Michael Madsen', 'Chris Penn', 'Steve Buscemi', 'Lawrence Tierney'],
    genres: ['crime', 'thriller'],
    poster_url: 'https://image.tmdb.org/t/p/w500/xi8Iu6qyTfyZVDVy60raIOYJJmk.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/jwt159hXWA9Q5xpBo8hWb3zwLi7.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=2KLZ4fSXtgI',
    description_ar: 'تشير عملية  سطو فاشلة إلى وجود مخبر شرطة ، ويتزايد الضغط في أعقاب ذلك في أحد المستودعات. الجريمة تولد العنف بينما يتفكك الناجون - المخضرم السيد وايت ، الوافد الجديد السيد أورانج ، السيكوباتي المشروط السيد بلوند ، ابن عرس المشاجرة السيد بينك ونيس جاي إيدي.',
    description_en: 'A botched robbery indicates a police informant, and the pressure mounts in the aftermath at a warehouse. Crime begets violence as the survivors -- veteran Mr. White, newcomer Mr. Orange, psychopathic parolee Mr. Blonde, bickering weasel Mr. Pink and Nice Guy Eddie -- unravel.',
    description_fr: 'Après un hold‐up manqué, des cambrioleurs de haut vol font leurs comptes dans une confrontation violente, pour découvrir lequel d’entre eux les a trahis.',
    description_es: 'Una banda organizada formada por seis individuos es contratada para dar un golpe. Anteriormente varios de los miembros no se conocían entre sí, por lo que entre ellos usan nombres en clave. El objetivo: atracar una empresa para llevarse unos diamantes. Pero, antes de que suene la alarma, la policía ya está allí. Algunos mueren en el atraco, y el resto se reúne en el lugar convenido.',
    description_tr: 'Bir grup suçlu, bir mücevher deposunu soyarlar. Polis o kadar çabuk peşlerine düşer ki aralarında bir muhbir olduğundan şüphelenirler. Soygundan hemen sonrasıyla başlayan film, olayın öncesine dönüp soygunun planlanması aşamasını anlatıyor. Ünlü karakter oyuncularından oluşan kadroyu da bu bölümde tanıyoruz.Bol aksiyon, kan ve şiddet içeren, klasikleşmiş bir Tarantino yapımı...',
    description_de: 'Ein perfekt geplanter Coup endet in einem rücksichtslosen Psycho-Horrortrip, der blutige Opfer fordert. Beteiligt sind sechs elegant gekleidete Profi-Gangster, die zu einem Überfall auf ein Juweliergeschäft zusammenkommen. Alles, was die Gentlemen voneinander wissen, sind die Decknamen, die ihnen ihr Auftraggeber Joe Cabot gegeben hat. Mr. White, Mr. Orange, Mr. Pink, Mr. Blonde, Mr. Blue, Mr. Brown. Doch der todsichere Coup misslingt, die Polizei war informiert. Am geheimen Treffpunkt, einem leerstehenden Lagerhaus, wird ein Verdacht zur Gewissheit: unter ihnen ist ein Spitzel. Tödliches Misstrauen macht sich breit. Während einer der Gangster zu verbluten droht, entwickeln sich die anderen zu reißenden Bestien, die weder vor der Folter an einem gekidnappten Polizisten noch vor blutiger Gewalt untereinander zurückschrecken.',
    description_ja: '宝石強盗を実行するために集められた、お互いに名前も素性も知らない6人のクセ者たち。完璧な計画のはずが、彼らは警官隊の襲撃を受ける。誰かが警察に通じていたのだ。命からがら集合場所に集まった彼らの心に、仲間への不信感がわき起こる……。',
    description_pt: 'Uma quadrilha de ladrões, em fuga de um assalto malsucedido, reencontra-se. Nenhum deles se conhece, foram chamados para o trabalho por um chefe a todos superior e usam alcunhas em lugar dos nomes verdadeiros. Eles sabem que um deles é um informador da Polícia e que o assalto fracassou devido a essa traição. Resta saber quem.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 1.2,
    box_office_million: 3,
    duration: 99, language: 'EN', country: 'US',
    reviews_count: 2449, is_featured: false, release_date: '1992-09-02', tags: ['crime', 'thriller', '1992', 'tarantino'],
    pros_ar: ['إخراج متميز', 'قصة مشوقة', 'أداء رائع للممثلين'],
    cons_ar: ['وتيرة بطيئة في بعض المشاهد', 'يحتاج تركيزاً عالياً'],
    pros_en: ['Strong direction', 'Compelling story', 'Great performances'],
    cons_en: ['Slow pacing in some scenes', 'Requires close attention'],
