    id: '148', slug: 'the-hunt', title: 'The Hunt', title_ar: 'Jagten', year: 2012,
    director: 'Thomas Vinterberg', director_ar: 'Thomas Vinterberg',
    cast: ['Mads Mikkelsen', 'Thomas Bo Larsen', 'Annika', 'Lasse Fogelstrøm', 'Susse Wold', 'Anne Louise Hassing'],
    genres: ['drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/jkixsXzRh28q3PCqFoWcf7unghT.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/jmVWlCZ8hRtmrQGbKXXFHsrSohp.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=BSVDnUgJVYY',
    description_ar: 'يعيش المعلم حياة منعزلة ، بينما يكافح طوال الوقت من أجل حضانة ابنه. تتحسن حياته ببطء عندما يجد الحب ويتلقى أخبارًا جيدة من ابنه ، لكن حظه الجديد على وشك أن يتفكك بوحشية بسبب كذبة صغيرة بريئة.',
    description_en: 'A teacher lives a lonely life, all the while struggling over his son’s custody. His life slowly gets better as he finds love and receives good news from his son, but his new luck is about to be brutally shattered by an innocent little lie.',
    description_fr: 'Après un divorce difficile, Lucas, quarante ans, a trouvé une nouvelle petite amie, un nouveau travail et il s’applique à reconstruire sa relation avec Marcus, son fils adolescent. Mais quelque chose tourne mal. Presque rien. Une remarque en passant. Un mensonge fortuit. Et alors que la neige commence à tomber et que les lumières de Noël s’illuminent, le mensonge se répand comme un virus invisible. La stupeur et la méfiance se propagent et la petite communauté plonge dans l’hystérie collective, obligeant Lucas à se battre pour sauver sa vie et sa dignité.',
    description_es: 'Tras un divorcio difícil, Lucas, de cuarenta años, ha encontrado una nueva novia, un nuevo trabajo y se dispone a reconstruir su relación con Marcus, su hijo adolescente. Pero algo va mal. Un detalle. Un comentario inocente. Una mentira fortuita. Y mientras la nieve comienza a caer y las luces de Navidad se iluminan, la mentira se extiende como un virus invisible. El estupor y la desconfianza se propagan y la pequeña comunidad se sumerge en la histeria colectiva, obligando a Lucas a luchar por salvar su vida y su dignidad.',
    description_tr: '40 yaşındaki Lucas, geçirdiği zor boşanma döneminin ardından hayatını yeniden düzene koyabilmenin peşindedir. Kreşte çalışan Lucas, aşkı yeniden bulurken bir yandan da ergenlik çağındaki oğluyla arasındaki sorunlu ilişkiyi onarmaya çalışmaktadır. Artık her şey yoluna girmek üzereyken sadece öylesine söylenmiş küçük bir yalan, içinde yaşadığı kasabaya bir virüs gibi yayılır ve Lucas kendini hayatı ve saygınlığı için savaşırken bulur.',
    description_de: 'Lucas musste einige Schicksalsschläge hinnehmen, doch jetzt geht es in seinem Leben langsam wieder bergauf. Er hat eine neue Stelle in einem Kindergarten gefunden und auch die hübsche Aushilfe Nadja fühlt sich zu ihm hingezogen. Auch sein Sohn Marcus möchte lieber bei seinem Vater als bei seiner Mutter leben. In den Kindergarten geht die kleine Klara, die Tochter seines besten Freundes Theo, die ihn besonders gut leiden kann. Einer Kindergartenleiterin erzählt Klara, Lucas habe sie geküsst und ihr sein Geschlechtsteil gezeigt, denn dass würden Liebende tun, so habe es ihr großer Bruder ihr erzählt. Lucas ist entsetzt, als er hört, was ihm vorgeworfen wird. Doch da hat das Gerücht schon in der gesamten Nachbarschaft die Runde gemacht. Der unschuldige Lucas fühlt sich sicher und denkt, dass sich alles schon von alleine beruhigen wird, doch das Gegenteil trifft ein: Die Hexenjagd auf ihn nimmt dramatische Züge an.',
    description_ja: '“北欧の至宝”と称される名優、マッツ・ミケルセンを主演に迎えたサスペンス・ドラマ。一人の少女の作り話によって、変質者の烙印を押されてしまった幼稚園教師のルーカス。全てを失った彼はさらなる迫害の標的となり……。',
    description_pt: 'Depois de um divórcio complicado, a sorte de Lucas parece estar a mudar. Tem uma namorada que o compreende, um novo trabalho na escola e está a recuperar a sua relação com Marcus, o filho adolescente. Porém, uma mentira impiedosa espalha-se pela comunidade e a desconfiança abate-se sobre os que habitantes da pequena vila dinamarquesa.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 3.8,
    box_office_million: 18,
    duration: 116, language: 'DA', country: 'DK',
    reviews_count: 1595, is_featured: false, release_date: '2012-10-25', tags: ['drama', '2012', 'vinterberg'],
    pros_ar: ['عمق درامي استثنائي', 'أداء تمثيلي رائع', 'قصة إنسانية مؤثرة'],
    cons_ar: ['وتيرة بطيئة في بعض المشاهد', 'يحتاج تركيزاً عالياً'],
    pros_en: ['Exceptional dramatic depth', 'Outstanding performances', 'Emotionally powerful story'],
    cons_en: ['Slow pacing in some scenes', 'Requires close attention'],
