    id: '149', slug: 'lock-stock-and-two-smoking-barrels', title: 'Lock, Stock and Two Smoking Barrels', title_ar: 'Lock, Stock and Two Smoking Barrels', year: 1998,
    director: 'Guy Ritchie', director_ar: 'Guy Ritchie',
    cast: ['Vinnie Jones', 'Jason Flemyng', 'Dexter Fletcher', 'Nick Moran', 'Jason Statham', 'Steven Mackintosh'],
    genres: ['comedy', 'crime'],
    poster_url: 'https://image.tmdb.org/t/p/w500/6pJB2t3MbQUy9m5pFIBHXLqnqNd.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/cXQH2u7wUIX1eoIdEj51kHXoWhX.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=HY7mRdQuUSw',
    description_ar: 'يحتاج قرش البطاقة وأصدقاؤه المجندون عن غير قصد إلى جني الكثير من الأموال بسرعة بعد خسارة مباراة بوكر بسيطة. للقيام بذلك قرروا القيام بسرقة عصابة صغيرة تعمل خارج الشقة المجاورة.',
    description_en: 'A card shark and his unwillingly-enlisted friends need to make a lot of cash quick after losing a sketchy poker match. To do this they decide to pull a heist on a small-time gang who happen to be operating out of the flat next door.',
    description_fr: 'Eddy, un joueur invétéré, s\'apprête à participer à la plus grosse partie de cartes de sa vie avec un enjeu de cent mille Livres, somme qu\'il a durement amassée avec ses trois acolytes, Tom, Baco et Soap. Eddy est considéré comme l\'un des meilleurs joueurs du circuit, mais la partie s\'avère être un coup monté à l\'issue duquel il doit cinq cent mille Livres à son adversaire Hatchet Harry. Ce dernier lui donne une semaine pour réunir cette somme, sinon il aura les doigts coupés. Seul JD, le père d\'Eddy, pourrait annuler la dette en cédant son bar à son vieux rival, Harry.',
    description_es: 'Eddie convence a tres amigos para jugarse sus ahorros en una partida de cartas contra Harry el Hacha, un mafioso del barrio. La partida está amañada, y Eddie no sólo pierde todo el dinero sino que contrae una deuda de medio millón de libras, que debe pagar en el plazo de una semana. El mafioso pretende quedarse con el local de su padre para resarcirse de la deuda, pero los cuatro amigos planean saldarla de una forma mucho más arriesgada.',
    description_tr: 'Sevimli sokak serserisi Eddy hayatının kumarına üç arkadaşı ile zar zor kazandıkları 100 000 paundu yatıracaktır. Tom, Bacon ve Soap aralarında onu seçmişlerdi. Masadaki en kurt oyuncu oydu. Ama ne yazık ki tüm oyun önceden ayarlanmış bir düzenden başka bir şey değildir. Oyunun sonunda Hatchet Harry’e yarım milyon paund borçlanarak masadan kalkar. Harry Eddy’e bocunu ödemesi için bir hafta süre tanır. Aksi halde para yerine parmaklarını alacaklardır. Eddy ve arkadaşları gerekli parayı acilen bulabilmek için türlü yollara başvururlar. Bunlardan biri Eddy’nin babasının antika tüfeği ile hırsızlığa bile yeltenmektir. Hepsi başarısızlıkla sonuçlanır. Oysaki ellerindekinin kıymetini bilmemektedirler...',
    description_de: 'Satte 100.000 Pfund haben die Gelegenheitsgauner Eddy und seine Freunde Tom, Bacon und Soap aufgetrieben, um bei einer Poker-Runde das Ding ihres Lebens zu drehen. Poker-König Eddy, dessen abgebrühte Kaltschnäuzigkeit bisher immer Erfolg versprach, nimmt an einer illegalen Profi-Runde teil. Klar, daß er dabei auf übelste Weise über den Tisch gezogen wird. Das Resultat: Eddy verliert nicht nur den kompletten Einsatz, sondern steht auch noch mit einer halben Million Pfund Schulden bei dem berüchtigten Unterweltkönig Hatchet Harry in der Kreide. Eine Woche bleibt ihnen, das Geld zurückzuzahlen: ansonsten werden Eddy und seine Freunde für jeden Tag, den sie das Ultimatum überschreiten, einen Finger verlieren. Not macht bekanntlich erfinderisch, und da die Jungs keine Lust haben zukünftig fingerlose Handschuhe zu tragen, überfallen sie kurzerhand eine Gang im Nachbarhaus. Dumm nur, daß es sich bei der erbeuteten Kohle schon um ebenfalls geklaute Drogengelder handelt...',
    description_ja: 'ガイ・リッチー監督・脚本によるクライム・ムービー。一攫千金を狙う4人の若者を軸に、ギャングやマフィアが入り交じって繰り広げる群像劇を独特のユーモアを交えて描く。巧妙なストーリー展開やテンポある演出に加え、多彩な登場人物が見せる妙な味わいが秀逸。ロンドンの下町に生きるエディはある日、仲間3人から金を集め、ギャンブルに投資するが惨敗。逆にその元締めに多額の借金を背負ってしまう。返済猶予は一週間。途方に暮れるエディたちだったが、彼らは偶然隣人の強盗計画を耳にする。',
    description_pt: 'Após um jogo de cartas viciado, quatro companheiros vêem-se seriamente em dívida com um duro do East End e os seus brutamontes. Ao ouvir os vizinhos planearem assaltar um grupo de cultivadores de droga inexperientes, os nossos heróis decidem apanhar os assaltantes logo a seguir. A confusão começa realmente quando um par de espingardas de repetição desaparecem numa vigarice completamente diferente.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 1.4,
    box_office_million: 28,
    duration: 105, language: 'EN', country: 'GB',
    reviews_count: 5051, is_featured: false, release_date: '1998-08-28', tags: ['comedy', 'crime', '1998', 'ritchie'],
    pros_ar: ['إخراج متميز', 'قصة مشوقة', 'أداء رائع للممثلين'],
    cons_ar: ['وتيرة بطيئة في بعض المشاهد', 'يحتاج تركيزاً عالياً'],
    pros_en: ['Strong direction', 'Compelling story', 'Great performances'],
    cons_en: ['Slow pacing in some scenes', 'Requires close attention'],
