    id: '162', slug: 'la-haine', title: 'La Haine', title_ar: 'La Haine', year: 1995,
    director: 'Mathieu Kassovitz', director_ar: 'Mathieu Kassovitz',
    cast: ['Vincent Cassel', 'Hubert Koundé', 'Saïd Taghmaoui', 'Abdel Ahmed Ghili', 'Solo', 'Joseph Momo'],
    genres: ['drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/8rgPyWjYZhsphSSxbXguMnhN7H0.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/k61xLJgPo7ScxHLLiBzTM9IDaB7.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=FKwcXt3JIaU',
    description_ar: 'بعد ليلة من أعمال الشغب الفوضوية في إحدى ضواحي باريس الهامشية ، يتجول ثلاثة أصدقاء شبان ، وهم فينز وهوبير وسعيد ، في أرجاء المكان شاغرًا ينتظرون أخبارًا عن الحالة الصحية لصديق مشترك أصيب بجروح خطيرة أثناء مواجهة الشرطة.',
    description_en: 'After a chaotic night of rioting in a marginal suburb of Paris, three young friends, Vinz, Hubert and Saïd, wander around unoccupied waiting for news about the state of health of a mutual friend who has been seriously injured when confronting the police.',
    description_fr: 'Trois copains d\'une banlieue ordinaire traînent leur ennui et leur jeunesse qui se perd. Ils vont vivre la journée la plus importante de leur vie après une nuit d\'émeutes provoquée par le passage à tabac d\'Abdel Ichah par un inspecteur de police lors d\'un interrogatoire.',
    description_es: 'Tras una caótica noche de disturbios en un suburbio marginal de París, tres jóvenes amigos, Vinz, Hubert y Saïd, deambulan desocupados esperando noticias sobre el estado de salud de un amigo común que ha resultado gravemente herido al enfrentarse a la policía.',
    description_tr: 'Paris’in gettolarında hararetli saatler yaşanmaktadır. Grup halinde dolaşan yerel gençlerle, çevreyi kuşatan polisler arasında nefret dolu bakışlardan oluşan bir gerilim vardır. Mahallenin gençlerinden Abdel, polis soruşturması sırasında dövüldüğü için hastanede ölüm döşeğinde yatmaktadır. Arkadaşı Vinz ise, Abdel’in ölmesi durumunda bir polis vurmaya ant içer.',
    description_de: 'In den tristen Sozialbausiedlungen der Pariser Vororte brechen Unruhen aus, nachdem ein 16-jähriger Araber von der Polizei fast zu Tode geprügelt wurde. Nach einer Nacht voller Gewalt zwischen Jugendlichen und der Polizei herrscht Ausnahmezustand. Getrieben von Hass gegen das System stehen die Freunde Hubert, Saïd und Vinz an vorderster Front, an einem Tag, der ihr Leben verändern wird.',
    description_ja: 'After a chaotic night of rioting in a marginal suburb of Paris, three young friends, Vinz, Hubert and Saïd, wander around unoccupied waiting for news about the state of health of a mutual friend who has been seriously injured when confronting the police.',
    description_pt: 'Três jovens sem perspetivas de futuro ocupam o seu tempo deambulando pelas ruas dos bairros de betão dos subúrbios de Paris. Quando um jovem árabe é vítima de violência policial e fica em estado de coma a situação torna-se explosiva.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
