    id: '163', slug: 'metropolis', title: 'Metropolis', title_ar: 'Metropolis', year: 1927,
    director: 'Fritz Lang', director_ar: 'Fritz Lang',
    cast: ['Gustav Fröhlich', 'Brigitte Helm', 'Alfred Abel', 'Rudolf Klein-Rogge', 'Theodor Loos', 'Fritz Rasp'],
    genres: ['drama', 'scifi'],
    poster_url: 'https://image.tmdb.org/t/p/w500/kr9wXRN23zLuWJIelahas1mtnYj.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/eeMoFKxjjiCi6iep2GEZtSAMYIr.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=ZAvzaOxDt2c',
    description_ar: 'في مدينة مستقبلية منقسمة بحدة بين الطبقة العاملة ومخططي المدينة ، يقع ابن العقل المدبر للمدينة في حب نبي من الطبقة العاملة يتنبأ بمجيء المنقذ للتوسط في خلافاتهم.',
    description_en: 'In a futuristic city sharply divided between the rich and the poor, the son of the city\'s mastermind meets a prophet who predicts the coming of a savior to mediate their differences.',
    description_fr: 'En 2026, une métropole à l’architecture fantastique vit sous le joug d’un groupe de tyrans. Les aristocrates se prélassent et se divertissent dans de somptueuses demeures et de luxuriants jardins, tandis que la grande masse de la population travaille, dort et survit durement dans les profondeurs de la terre. Le fils du maître de la ville découvre avec effarement l’existence du monde souterrain, où se rencontrent en secret les ouvriers, peu enclins à supporter pour toujours leur situation. Pendant ce temps, un savant invente une femme‐robot qui doit détourner les opprimés de leur révolte…',
    description_es: 'En una megalópolis del año 2000, los obreros están condenados a vivir recluidos en un gueto subterráneo, donde se encuentra el corazón industrial de la ciudad. Sin embargo, incitados por un robot, se rebelan contra la clase dominante y amenazan con destruir la ciudad exterior. Freder (Gustav Frölich), el hijo del soberano de Metrópolis, y María, una muchacha de origen humilde, intentarán evitar la destrucción apelando a los sentimientos y al amor.',
    description_tr: 'Gelecek zaman… İnsanlar iki gruba ayrılmış durumdadır: düşünenler (ancak hiçbir makinenin nasıl çalıştığını bilmiyorlar) ve çalışanlar (fikir sahibi değiller). Düşünenler planları yapıyor, çalışanlar da bunları uyguluyorlar. İki grup da tam değildir ama birleşince bir bütün oluyorlar. Bir gün düşünenlerden biri yeraltına çalışanların yanına iner. Gördükleriyle birlikte hayatın akışı değişmeye başlar…',
    description_de: 'Johann Fredersen, ein Großindustrieller, herrscht über die Stadt Metropolis. Dort leben, gespalten in einer Zweiklassengesellschaft, die feinen Herren hoch oben in Hochhäusern, die Arbeiter hingegen tief unter der Erde. Eines Tages taucht Maria, die Heldin der Unterstadt, in den Spielwiesen der Reichen auf und fordert die Befreiung der unterdrückten Arbeiter. Freder, der Sohn des Herrschers, verliebt sich in sie. Der Erfinder Rotwang wird von Freders Vater Johann sodann beauftragt einem Roboter das Aussehen Marias zu geben. Die Roboter-Maria soll die Arbeiter aufstacheln, damit das Establishment noch härter durchgreifen kann. Der Plan hat Erfolg.',
    description_ja: '科学の飛躍的な発展の結果、労働者たちは地下に押しやられ、巨大な工場で家畜同然に管理されている一方、資本家たちは地上で享楽的生活を送っている。社長の息子は地下に降りて、彼らの悲惨な生活を知る。労働者の娘マリアは、労使間に人間的な絆が皆無であることを仲間に訴え、これがストライキの気運を生む。そこで社長はマリアを監禁、彼女そっくりの人造人間を作って事態収拾にあたるが、人造人間は狂い始める。',
    description_pt: 'No futuro, a sociedade de Metropolis está dividida em dois grupos: os trabalhadores,que vivem debaixo da terra e fazem as máquinas funcionar e a classe dominante que vive à suprefície. Os trabalhadores são dirigidos por Maria que quer encontrar um mediador entre a classe dominante e os trabalhadores, pois ela acredita que entre o cérebro e os músculos é necessário um coração. Maria encontra Freder Fredersen, o filho do senhor de Metropolis, Joh Fredersen e apaixonam-se. Entretanto, Joh decide que os trabalhadores já não são necessários a Metropolis e usa um robô para fingir que é Maria e fomentar a revolução entre a classe trabalhadora para a eliminar.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 5.3,
    box_office_million: 1,
