    id: '165', slug: 'hoppers', title: 'Hoppers', title_ar: 'هوبرز', year: 2026,
    director: 'Daniel Chong', director_ar: 'Daniel Chong',
    cast: ['Piper Curda', 'Bobby Moynihan', 'Jon Hamm', 'Kathy Najimy', 'Dave Franco', 'Eduardo Franco'],
    genres: ['adventure', 'animation', 'comedy'],
    poster_url: 'https://image.tmdb.org/t/p/w500/xjtWQ2CL1mpmMNwuU5HeS4Iuwuu.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/u53UYu5XG2hNgWGvs3xGhAVzypl.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=PypDSyIRRSs',
    description_ar: 'تدور قصة الفيلم حول فتاة تُدعى "مايبل تاناكا"، الشابة الشغوفة بالحيوانات، التي ترتبط عاطفيًا بمكان طبيعي كانت تزوره مع جدتها. لكن هذا المكان مهدد بسبب مشروع طريق سريع يخطط له العمدة وبينما تحاول إنقاذه، تكتشف تقنية تمكّن البشر من الدخول في أجساد حيوانات آلية والتواصل مع الحياة البرية، فتقرر استخدامها وتتحول إلى قندس.',
    description_en: 'Scientists have discovered how to \'hop\' human consciousness into lifelike robotic animals, allowing people to communicate with animals as animals. Animal lover Mabel seizes an opportunity to use the technology, uncovering mysteries within the animal world beyond anything she could have imagined.',
    description_fr: 'Mabel, une amoureuse des animaux, utilise une nouvelle technologie pour "transférer" sa conscience dans un robot-castor réaliste et communiquer directement avec les animaux. Alors qu\'elle découvre des mystères du monde animal dépassant tout ce qu\'elle aurait pu imaginer, Mabel se lie d\'amitié avec Roi Georges, un charismatique castor, et doit rallier tout le règne animal pour faire face à une menace humaine majeure et imminente : le maire Jerry Generazzo, un beau parleur.',
    description_es: 'Una amante de los animales aprovecha la oportunidad de utilizar una tecnología que coloca su conciencia en un castor robótico, descubriendo misterios dentro del mundo animal que van más allá de lo que podría haber imaginado.',
    description_tr: 'Hayvansever Mabel, insan bilincini gerçeğe yakın robotik hayvanlara aktarmak için tasarlanmış akıllı yeni bir teknolojiyi kullanır. Bu sayede kunduzlarla iletişim kurar ve hayvanlar dünyasında hayal edebileceğinin ötesinde gizemleri açığa çıkarır.',
    description_de: 'Die Tierliebhaberin Mabel nutzt eine neuartige Technologie, um ihr Bewusstsein in einen täuschend echt aussehenden Biberroboter zu übertragen und so direkt mit der Tierwelt zu kommunizieren. Dabei entdeckt sie ungeahnte Geheimnisse und schließt Freundschaft mit dem charismatischen König George. Als der schleimige Bürgermeister Jerry Generazzo jedoch zur Bedrohung für den Lebensraum wird, muss Mabel das gesamte Tierreich vereinen, um sich der menschlichen Gefahr entgegenzustellen.',
    description_ja: 'ディズニー＆ピクサー最新作！ もしもビーバーになって、＜動物の世界＞に潜入できたら？  ある目的のため、ビーバー型ロボットに意識を“ホップ”させたメイベルは夢見ていた動物との会話に大喜びするが、人間の世界を揺るがす動物たちのとんでもない計画を知ってしまう。ビーバーになった彼女が巻き起こす奇跡とは―？',
    description_pt: 'Os cientistas descobriram como fazer a consciência humana "saltar" para o interior de animais robóticos sofisticados, permitindo às pessoas comunicar com os animais enquanto animais! Esta aventura apresenta Mabel, uma amante de animais, que aproveita uma oportunidade para usar a tecnologia, e desvenda mistérios do mundo animal que ultrapassam tudo o que poderia imaginar.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
