    id: '166', slug: 'das-boot', title: 'Das Boot', title_ar: 'Das Boot', year: 1981,
    director: 'Wolfgang Petersen', director_ar: 'Wolfgang Petersen',
    cast: ['Jürgen Prochnow', 'Herbert Grönemeyer', 'Klaus Wennemann', 'Hubertus Bengsch', 'Martin Semmelrogge', 'Bernd Tauber'],
    genres: ['drama', 'history'],
    poster_url: 'https://image.tmdb.org/t/p/w500/u8FhQPncOAkwcei2OI9orPWhV6K.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/zGgIlpKE2xP18bhCGsnn79vh80j.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=KhNnU4h1Q50',
    description_ar: 'غواصة ألمانية تطارد سفن الحلفاء خلال الحرب العالمية الثانية ، لكنها سرعان ما تصبح مطاردة. يحاول الطاقم البقاء على قيد الحياة تحت السطح ، بينما يمتد كل من القارب وأنفسهم إلى أقصى حدودهم.',
    description_en: 'A German submarine hunts allied ships during the Second World War, but it soon becomes the hunted. The crew tries to survive below the surface, while stretching both the boat and themselves to their limits.',
    description_fr: 'Pendant la deuxième Guerre Mondiale, 40 000 sous-mariniers allemands envoyés par Hitler embarquent pour une mission de routine dans l\'Atlantique Nord. L\'insouciance règne à bord. Ce qu\'ils ne savent pas, c\'est que seuls 10 000 hommes retourneront chez eux vivants.',
    description_es: 'Un submarino alemán de la Segunda Guerra Mundial es el escenario en el que un grupo de jóvenes soldados, dispuesto a defender su patria, tendrá que someterse a una dura convivencia, tras descubrir que han sido enviados a realizar una misión probablemente suicida.',
    description_tr: '1979 yılında çekilmiş 1981 yılında vizyona giren, İkinci Dünya Savaşı\'nda U-96 adlı tip 7 sınıfı Alman U bot mürettebatını konu alan film. Savaşta Alman denizcilerin hayatlarını, içinde bulundukları psikolojik durumları görsel bir anlatış biçimiyle dile getirmektedir. İkinci Dünya Savaşı\'nda görev yapan U-96 tipi bir Alman denizaltısı Atlas Okyanusu\'ndaki normal devriye görevine çıkar. Gemide görevli personel haricinde bir subay da denizaltında yaşananları kaydetmek için sefere katılır. Gemi normal seyrinde iken okyanusta detroyer koruması olmadan seyreden 5 gemilik bir filoyla karşılaşır. Kaptan biraz tereddütden sonra saldırı emri verir.',
    description_de: 'Der Kriegsberichterstatter Werner geht 1941 an Bord von U-96, das den Auftrag hat englische Transportschiffe zu versenken. Werner soll der Heimatfront von den Heldentaten des Kapitäns und seiner Mannschaft berichten. Doch schnell wird der Jäger zum Gejagten und der Atlantik entpuppt sich bald als nasskalte Hölle für die Besatzung. Ein Albtraum aus Klaustrophobie und Todesangst beginnt.',
    description_ja: '第2次世界大戦の1941年。ナチスドイツに占領されたフランスのラ・ロシェルの港から、出撃命令によって出航する潜水艦U96にヴェルナー（ヘルバート・グリューネマイヤー）が乗り込む。ベテランの艦長（ユルゲン・プロフノウ）や乗組員に囲まれながら、荒れた海での過酷な哨戒、次々と爆雷を放ってくる敵駆逐艦との攻防、海の藻くずと化していく敵の姿など、戦争の現実を次々と目の当たりにするヴェルナー。そんな中、U96に新たな命令が下される。',
    description_pt: 'Retracta o inferno dos tripulantes de um submarino alemão que, em 1942, participou da Batalha do Atlântico. De modo realista, conhecemos como um simples submarino lutou contra os navios Ingleses e todo o sofrimento de quando eram atacados.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
    imdb_rating: 8.1, rotten_tomatoes: 81,
    budget_million: 14.0,
    box_office_million: 85,
