    id: '167', slug: 'all-about-eve', title: 'All About Eve', title_ar: 'All About Eve', year: 1950,
    director: 'Joseph L. Mankiewicz', director_ar: 'Joseph L. Mankiewicz',
    cast: ['Bette Davis', 'Anne Baxter', 'George Sanders', 'Celeste Holm', 'Gary Merrill', 'Hugh Marlowe'],
    genres: ['drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/blBzZaatPWVuWpXEnPscMA4Xp6m.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/zAL3LOswagN9onjN8DPcNFTqKuD.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=MILphnfj2mo',
    description_ar: 'من اللحظة التي تلمح فيها معبودها عند باب المسرح ، عازمة إيف هارينجتون على أخذ زمام السلطة بعيدًا عن الممثلة الكبيرة مارجو تشانينج. تشق Eve طريقها إلى دور Margo في برودواي ، وتصبح ضجة كبيرة وتسبب اضطرابًا في حياة صديق Margo المخرج وكاتبها المسرحي وزوجته. فقط الناقد الدرامي الساخر يرى حواء ، معجبًا بجرأتها ونمط الخداع المثالي.',
    description_en: 'From the moment she glimpses her idol at the stage door, Eve Harrington is determined to take the reins of power away from the great actress Margo Channing. Eve maneuvers her way into Margo\'s Broadway role, becomes a sensation and even causes turmoil in the lives of Margo\'s director boyfriend, her playwright and his wife. Only the cynical drama critic sees through Eve, admiring her audacity and perfect pattern of deceit.',
    description_fr: 'Ève Harrington reçoit, des mains d\'un vieil acteur, le prix Sarah Siddons. L\'entourage de celle-ci se souvient de son ascension.',
    description_es: 'Una joven que aspira a convertirse en actriz y triunfar en los escenarios se las ingenia para introducirse en un grupo de actores de teatro y hacerse amiga y confidente de una famosa y veterana actriz. El deseo de actuar y los celos la consumen hasta el punto de traicionar a sus compañeros en su escalada hacia el éxito. Ella halaga, atrae, seduce, pero también pisotea a todo el que se cruza en su camino: escritores, directores, productores. Sólo un inteligente crítico teatral adivina lo que se esconde tras su dulce apariencia, sólo él es capaz de ver a Eva al desnudo.',
    description_tr: 'En İyi Film başta olmak üzere tam 6 Oscar\'lı bir başyapıt  Ünlü yıldız Margo Channing (Bette Davis), Eve (Anne Baxter) adlı genç bir kızla tanışır Eve, Margo\'nun büyük bir hayranıdır ve kısa sürede onun güvenini kazanmayı başarır; hatta onun evine taşınır Oysa masum görünüşlü bu kızın başka amaçları vardır Margo\'nun yerini almak isteyen Eve, sinsi planlarını sırayla uygulamaya başlamıştır Margo\'nun yıldızı sönerken Eve ise başarıdan başarıya koşmaktadır...',
    description_de: 'Die junge Eve Harrington ist eine begeisterte Verehrerin der Theaterschauspielerin Margo Channing  Immer wieder sieht sie sich ihren Star in der Aufführung des Stückes „Gereift in Holz“ an. Mit hartnäckiger Beharrlichkeit gelingt es ihr schließlich, Margo kennenzulernen und das Vertrauen der Schauspielerin zu gewinnen. Fortan hält sich Eve immer im Umfeld Margos auf, um ihren Star mit Tatkraft zu unterstützen. Als Margo merkt, dass ihre junge Verehrerin nicht nur uneigennützige Ziele verfolgt, ist es bereits zu spät, um Eve wieder los zu werden. Denn Eve ist eine Meisterin der Intrige …',
    description_ja: 'ある日、新進女優イヴ・ハリントンはアメリカ演劇界の栄えある賞に輝いた。だが、彼女がここまで上り詰めるには、一部の関係者たちしか知り得ない紆余曲折の経緯があった。８ヶ月前、田舎からニューヨークへ出てきたイヴは、ひょんなことから憧れの舞台女優マーゴの住み込み秘書となった。するとイヴはこれを皮切りに、劇作家や有名批評家に巧く取り入り、マーゴまでも踏み台にしてスター女優へのし上がっていく…。  　監督マンキウィッツ自身による見事な脚本と、名優たちの火花散らす熱演とが融合し、その年のアカデミー賞をほぼ独占する形となった、バックステージものの最高作。田舎からニューヨークへ出、大女優（Ｂ・デイヴィス）の付き人となったのを皮切りに、有名批評家に取り入って大女優の代役から一躍、ブロードウェイの寵児にのし上がるヒロインを、Ａ・バクスターがまさに一世一代の体当たり芝居で演じきる。批評家のＧ・サンダースも、いつになく繊細な役柄を的確に表現し、オスカー助演賞を得た。まだ無名の頃のモンローが顔を出している。',
    description_pt: 'Margo Channing é uma reconhecida atriz da Broadway que está envelhecendo e Eve Harrington é uma jovem fã que consegue se infiltrar na vida de Channing e que acaba ameaçando sua carreira e relacionamentos pessoais. Filme baseado na obra The Wisdom of Eve, de Mary Orr.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
