    id: '168', slug: 'the-invisible-guest', title: 'The Invisible Guest', title_ar: 'الضيف الخفي', year: 2017,
    director: 'Oriol Paulo', director_ar: 'Oriol Paulo',
    cast: ['Mario Casas', 'Ana Wagener', 'Jose Coronado', 'Bárbara Lennie', 'Francesc Orella', 'Paco Tous'],
    genres: ['drama', 'thriller'],
    poster_url: 'https://image.tmdb.org/t/p/w500/fptnZJbLzKUHeNlYrAynbyoL5YJ.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/1ZSWFzAP4AZuFCigZZoib2RdcUO.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=epCg2RbyF80',
    description_ar: 'يستيقظ رجل أعمال شاب إلى جانب جثة عشيقته في غرفة فندق، فيستأجر محاميًا بارزًا ليعرف كيف انتهى به الأمر كمشتبه به في جريمة قتل.',
    description_en: 'Barcelona, Spain. Adrián Doria, a young and successful businessman accused of murder, meets one night with Virginia Goodman, an expert interrogation lawyer, in order to devise a defense strategy.',
    description_fr: 'Adrián Doria, homme d\'affaires à la réussite insolente, se réveille dans une chambre d\'hôtel, fermée de l\'intérieur, aux côtés de sa maîtresse… morte. Tout l\'accuse. Contre toute attente, il clame son innocence. La prestigieuse avocate Virginia Goodman assure sa défense. À la veille du procès, un mystérieux témoin à charge entre en jeu. Que s\'est-il réellement passé dans la chambre d\'hôtel ?',
    description_es: 'Barcelona, España. Adrián Doria, un joven y exitoso empresario acusado de homicidio, se reúne una noche con Virginia Goodman, una abogada experta en interrogatorios, con el propósito de urdir una estrategia de defensa.',
    description_tr: 'Adrian Doria kariyerinde hızla yükselen bir iş adamıdır. Evli bir adam olan Adrian, fotoğrafçı olan sevgilisi Laura’yı öldürmekle suçlanmaktadır. Adrian, kendisine güvenilir bir savunma yaratmak için tanık hazırlama ve adli bildirimlerde uzman deneyimli bir avukat olan Virginia Goodman ile tanışır. Adrian, Virgina’ya yaşanan olayları en başından anlatmaya başlar. Fakat Virginia hikayede bazı tutarsızlıklar fark eder ve onu hikayesinin karanlık noktalarını açığa çıkarması için zorlar.',
    description_de: 'Ein verschlossener Raum, eine Leiche und ein dringend Tatverdächtiger: Der erfolgreiche Geschäftsmann Adrián Doria, gleichzeitig der Liebhaber der Toten. Frau und Tochter hat er in der Folge bereits verloren, ebenfalls den Kampf um die öffentliche Meinung. Bis die Anwältin Virginia Goodman an seine Tür klopft – mit neuem Zeugen und neuen Fragen im Gepäck.',
    description_ja: 'Barcelona, Spain. Adrián Doria, a young and successful businessman accused of murder, meets one night with Virginia Goodman, an expert interrogation lawyer, in order to devise a defense strategy.',
    description_pt: 'Após se deparar com a sua agora falecida amante num quarto de hotel, um jovem empresário contrata um famoso advogado para perceber como se tornou suspeito de homicídio.',
    rating_overall: 8.2, rating_story: 8.2, rating_acting: 8.3, rating_direction: 8.1, rating_cinematography: 7.9, rating_music: 7.7,
