    id: '169', slug: 'harry-potter-and-the-deathly-hallows-part-2', title: 'Harry Potter and the Deathly Hallows: Part 2', title_ar: 'هاري بوتر ومقدسات الموت الجزء الثاني', year: 2011,
    director: 'David Yates', director_ar: 'David Yates',
    cast: ['Daniel Radcliffe', 'Emma Watson', 'Rupert Grint', 'Ralph Fiennes', 'Alan Rickman', 'Michael Gambon'],
    genres: ['adventure', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/c54HpQmuwXjHq2C9wmoACjxoom3.jpg',
